INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('cursor-ipad-workspace-start-plan', 'ua', 'tools', $t$Інструменти$t$, '#2dd4a0', $t$Cursor$t$, '2026-08-03', $t$Cursor додає агентів для Google Workspace, застосунок для iPad і бюджетний план для Індії$t$, $t$Cursor випустив три оновлення за тиждень. Плагіни для Google Workspace дозволяють агентам читати, писати та діяти в Gmail, Drive і Calendar. Cursor для iPad з'явився на всіх платних планах із закріпленими бічними чатами для спостереження за кількома агентами одночасно. Cursor Start запущено за Rs 649 на місяць для індійських розробників, включно з Grok 4.5 і Composer.$t$, $t$<p>Cursor випустив три окремі оновлення в період з 28 липня по 3 серпня, і разом вони говорять про напрямок розвитку більше, ніж будь-яке з них окремо.</p>
<h2>Плагіни для Google Workspace</h2>
<p>Нові інтеграції дозволяють агентам Cursor <strong>читати, писати та діяти в Google Workspace</strong> — Gmail, Google Drive і Google Calendar. Це виводить агента за межі репозиторію. Інструмент для написання коду, який може прочитати специфікацію з Drive, перевірити календар і надіслати лист, — це вже не просто інструмент для написання коду.</p>
<h2>Cursor для iPad</h2>
<p>Підтримка iPad з'явилася на <strong>всіх платних планах</strong>, із закріпленими бічними чатами, що дозволяють спостерігати за роботою кількох агентів одночасно, повноцінним переглядом PR та реорганізованими інструментами для вхідних. Дизайн показує, чим став цей робочий процес: цінність полягає в нагляді за паралельними агентами, а не в наборі коду на планшеті.</p>
<h2>Cursor Start</h2>
<p>Для індійських розробників запущено бюджетний план за <strong>Rs 649 на місяць</strong>, що включає доступ до моделей Grok 4.5 і Composer, а також віддалене керування через iOS. Регіональне ціноутворення на такому рівні — це продуманий ринковий крок, а не просто знижка.</p>
<h2>Чому це важливо</h2>
<p>Спільна нитка тут — нагляд. Router (22 липня) обирає модель для кожного запиту, iPad дозволяє спостерігати за кількома агентами одночасно, а Workspace дає цим агентам доступ за межі коду. Cursor створює продукт для розробника, який запускає роботу і перевіряє її, а не пише кожен рядок сам.</p>
<p>Доступ до Workspace варто ретельно оцінити, перш ніж його вмикати. Агент із правом запису в пошту та календар має інший профіль ризику, ніж той, що обмежений git-репозиторієм, і масштаб наслідків помилки відповідно зростає.</p>
<h2>Що перевірити перед увімкненням доступу до Workspace</h2>
<p>Доступ на читання й запис до пошти, файлів і календаря суттєво розширює те, до чого може дотягнутися агент для написання коду. Надавайте найвужчі права доступу, необхідні для роботи процесу, тримайте агента подалі від спільних дисків, до яких у нього немає причин звертатися, і переконайтеся, що є аудиторський слід, перш ніж дозволяти йому діяти без нагляду. Ризик полягає не стільки в неправильній поведінці самого інструмента, скільки в тому, що агент виконає інструкції, знайдені в якомусь документі.</p>
<p>Варто також стежити за регіональним ціноутворенням: Rs 649 на місяць — це серйозна заявка на ринок розробників, який значною мірою був відрізаний від передових інструментів через ціну, а там, куди рухається Cursor у цьому напрямку, конкуренти зазвичай ідуть слідом.</p>$t$, true);

DELETE FROM news WHERE slug = 'cursor-ipad-workspace-start-plan' AND lang = 'he';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('cursor-ipad-workspace-start-plan', 'he', 'tools', $t$כלים$t$, '#2dd4a0', $t$Cursor$t$, '2026-08-03', $t$Cursor מוסיפה סוכני Google Workspace, אפליקציית iPad ותוכנית זולה להודו$t$, $t$Cursor השיקה שלושה שינויים בתוך שבוע. תוספי Google Workspace מאפשרים לסוכנים לקרוא, לכתוב ולפעול ב-Gmail, Drive ו-Calendar. Cursor for iPad הגיעה לכל התוכניות בתשלום עם צ'אטים נעוצים בסיידבר למעקב אחר כמה סוכנים בו-זמנית. Cursor Start הושקה במחיר Rs 649 לחודש למפתחים בהודו, כולל Grok 4.5 ו-Composer.$t$, $t$<p>Cursor השיקה שלושה שינויים נפרדים בין 28 ביולי ל-3 באוגוסט, ויחד הם מספרים יותר על הכיוון שלה מכל אחד מהם בנפרד.</p>
<h2>תוספי Google Workspace</h2>
<p>אינטגרציות חדשות מאפשרות לסוכני Cursor <strong>לקרוא, לכתוב ולפעול ב-Google Workspace</strong> — Gmail, Google Drive ו-Google Calendar. זה מזיז את הסוכן מעבר לגבולות המאגר (repository). כלי קידוד שיכול לקרוא מפרט מ-Drive, לבדוק יומן ולשלוח דוא"ל, הוא כבר לא רק כלי קידוד.</p>
<h2>Cursor for iPad</h2>
<p>תמיכה ב-iPad הגיעה <strong>לכל התוכניות בתשלום</strong>, עם צ'אטים בסיידבר שנשארים נעוצים כך שאפשר לעקוב אחר כמה סוכנים הרצים במקביל, סקירת PR מלאה, וכלי דואר נכנס מאורגנים מחדש. העיצוב מספר לך למה הפך זרימת העבודה: הערך הוא בפיקוח על סוכנים במקביל, לא בהקלדת קוד על טאבלט.</p>
<h2>Cursor Start</h2>
<p>תוכנית תקציבית הושקה למפתחים בהודו במחיר של <strong>Rs 649 לחודש</strong>, כולל גישה למודלים Grok 4.5 ו-Composer בתוספת שליטה מרחוק מ-iOS. תמחור אזורי בשיעור כזה הוא צעד שוק מכוון ולא הנחה.</p>
<h2>למה זה חשוב</h2>
<p>הקו המשותף הוא פיקוח. Router (22 ביולי) בוחר מודל לפי בקשה, ה-iPad מאפשר לצפות בכמה סוכנים בבת אחת, ו-Workspace נותנת לסוכנים האלה הישג יד מעבר לקוד. Cursor בונה עבור מפתח שמתחיל עבודה ובודק אותה, ולא כזה שכותב כל שורה.</p>
<p>גישת Workspace מצריכה בחינה קפדנית לפני הפעלתה. סוכן עם גישת כתיבה לדואר וליומן הוא פרופיל סיכון שונה מסוכן המוגבל למאגר git, ורדיוס הנזק של טעות גדל בהתאם.</p>
<h2>מה לבדוק לפני הפעלת גישת Workspace</h2>
<p>גישת קריאה וכתיבה לדואר, לקבצים וליומן היא הרחבה משמעותית של מה שסוכן קידוד יכול להגיע אליו. יש להעניק את ההיקפים המצומצמים ביותר שמאפשרים את זרימת העבודה לתפקד, לשמור את הסוכן מחוץ לכוננים משותפים שאין לו סיבה לגעת בהם, ולוודא שקיים מסלול בקרה (audit trail) לפני שמאפשרים לו לפעול ללא השגחה. הסיכון אינו כל כך התנהגות לא תקינה של הכלי, אלא סוכן שממלא הוראות שמצא בתוך מסמך.</p>
<p>גם תמחור אזורי כדאי לעקוב אחריו: Rs 649 לחודש הוא ניסיון רציני לפרוץ לשוק מפתחים שברובו נדחק מגישה לכלים המתקדמים ביותר, ולאן ש-Cursor פונה בעניין הזה, מתחרים נוהגים ללכת בעקבותיה.</p>$t$, true);

DELETE FROM news WHERE slug = 'cursor-ipad-workspace-start-plan' AND lang = 'fr';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('cursor-ipad-workspace-start-plan', 'fr', 'tools', $t$Outils$t$, '#2dd4a0', $t$Cursor$t$, '2026-08-03', $t$Cursor ajoute des agents Google Workspace, une application iPad et une offre à bas coût pour l'Inde$t$, $t$Cursor a déployé trois changements en une semaine. Les plugins Google Workspace permettent aux agents de lire, d'écrire et d'agir dans Gmail, Drive et Calendar. Cursor pour iPad est arrivé sur tous les forfaits payants avec des discussions épinglées dans la barre latérale pour surveiller plusieurs agents à la fois. Cursor Start a été lancé à 649 Rs par mois pour les développeurs indiens, avec notamment Grok 4.5 et Composer.$t$, $t$<p>Cursor a déployé trois changements distincts entre le 28 juillet et le 3 août, et pris ensemble, ils en disent plus sur l'orientation de l'entreprise que chacun d'eux séparément.</p>
<h2>Plugins Google Workspace</h2>
<p>De nouvelles intégrations permettent aux agents Cursor de <strong>lire, écrire et agir dans Google Workspace</strong> — Gmail, Google Drive et Google Calendar. Cela fait sortir l'agent du dépôt de code. Un outil de codage capable de lire une spécification depuis Drive, de consulter un calendrier et d'envoyer des e-mails n'est plus seulement un outil de codage.</p>
<h2>Cursor pour iPad</h2>
<p>La prise en charge de l'iPad est arrivée sur <strong>tous les forfaits payants</strong>, avec des discussions dans la barre latérale qui restent épinglées afin de pouvoir surveiller plusieurs agents en cours d'exécution simultanément, une revue complète des pull requests, et des outils de boîte de réception réorganisés. Cette conception indique ce qu'est devenu le flux de travail : la valeur réside dans la supervision d'agents en parallèle, et non dans la saisie de code sur une tablette.</p>
<h2>Cursor Start</h2>
<p>Un forfait économique a été lancé pour les développeurs indiens à <strong>649 Rs par mois</strong>, incluant l'accès aux modèles Grok 4.5 et Composer ainsi que le contrôle à distance depuis iOS. Une tarification régionale à ce niveau relève d'une démarche commerciale délibérée plutôt que d'une simple remise.</p>
<h2>Pourquoi c'est important</h2>
<p>Le fil conducteur, c'est la supervision. Router (22 juillet) choisit le modèle en fonction de la requête, l'iPad permet de surveiller plusieurs agents à la fois, Workspace donne à ces agents une portée qui dépasse le code. Cursor conçoit ses outils pour un développeur qui lance une tâche et en vérifie l'avancement, plutôt que pour celui qui écrit chaque ligne.</p>
<p>L'accès à Workspace mérite un examen approfondi avant d'être activé. Un agent disposant d'un accès en écriture aux e-mails et au calendrier présente un profil de risque différent de celui confiné à un dépôt git, et le rayon d'impact d'une erreur s'en trouve accru en conséquence.</p>
<h2>Ce qu'il faut vérifier avant d'activer l'accès à Workspace</h2>
<p>L'accès en lecture et en écriture aux e-mails, aux fichiers et au calendrier constitue un élargissement significatif de ce qu'un agent de codage peut atteindre. Accordez les autorisations les plus restreintes nécessaires au bon fonctionnement du flux de travail, gardez l'agent à l'écart des lecteurs partagés qu'il n'a aucune raison de consulter, et assurez-vous qu'une piste d'audit existe avant de le laisser agir sans supervision. Le risque ne réside pas tant dans un dysfonctionnement de l'outil que dans le fait qu'un agent suive des instructions trouvées dans un document.</p>
<p>La tarification régionale est également à surveiller : 649 Rs par mois représente une offre sérieuse destinée à un marché de développeurs qui s'est largement retrouvé exclu des outils de pointe en raison du prix, et là où Cursor s'engage sur ce terrain, les concurrents ont tendance à suivre.</p>$t$, true);

DELETE FROM news WHERE slug = 'cursor-ipad-workspace-start-plan' AND lang = 'pt';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('cursor-ipad-workspace-start-plan', 'pt', 'tools', $t$Ferramentas$t$, '#2dd4a0', $t$Cursor$t$, '2026-08-03', $t$Cursor adiciona agentes para Google Workspace, um app para iPad e um plano de baixo custo para a Índia$t$, $t$A Cursor lançou três novidades em uma semana. Plugins do Google Workspace permitem que agentes leiam, escrevam e ajam no Gmail, Drive e Calendar. O Cursor for iPad chegou a todos os planos pagos, com chats fixados na barra lateral para acompanhar vários agentes ao mesmo tempo. O Cursor Start foi lançado a Rs 649 por mês para desenvolvedores indianos, incluindo Grok 4.5 e Composer.$t$, $t$<p>A Cursor lançou três mudanças distintas entre 28 de julho e 3 de agosto, e juntas elas dizem mais sobre a direção da empresa do que qualquer uma delas isoladamente.</p>
<h2>Plugins do Google Workspace</h2>
<p>Novas integrações permitem que agentes do Cursor <strong>leiam, escrevam e ajam em todo o Google Workspace</strong> — Gmail, Google Drive e Google Calendar. Isso leva o agente para além do repositório. Uma ferramenta de codificação capaz de ler uma especificação no Drive, verificar uma agenda e enviar e-mails já não é apenas uma ferramenta de codificação.</p>
<h2>Cursor for iPad</h2>
<p>O suporte para iPad chegou a <strong>todos os planos pagos</strong>, com chats na barra lateral que ficam fixados para permitir o acompanhamento de vários agentes em execução simultânea, revisão completa de PRs e ferramentas de caixa de entrada reorganizadas. O design mostra o que o fluxo de trabalho se tornou: o valor está em supervisionar agentes em paralelo, não em digitar código em um tablet.</p>
<h2>Cursor Start</h2>
<p>Um plano econômico foi lançado para desenvolvedores indianos por <strong>Rs 649 por mês</strong>, incluindo acesso aos modelos Grok 4.5 e Composer, além de controle remoto via iOS. Um preço regional nesse nível é um movimento de mercado deliberado, e não um simples desconto.</p>
<h2>Por que isso importa</h2>
<p>O fio condutor é a supervisão. O Router (22 de julho) escolhe o modelo por requisição, o iPad permite acompanhar vários agentes ao mesmo tempo, e o Workspace dá a esses agentes alcance além do código. A Cursor está construindo para um desenvolvedor que inicia um trabalho e depois o verifica, em vez de um que escreve cada linha.</p>
<p>O acesso ao Workspace merece uma análise rigorosa antes de ser ativado. Um agente com acesso de escrita a e-mail e agenda representa um perfil de risco diferente de um restrito a um repositório git, e o raio de impacto de um erro cresce na mesma proporção.</p>
<h2>O que verificar antes de ativar o acesso ao Workspace</h2>
<p>O acesso de leitura e escrita a e-mail, arquivos e agenda é uma expansão significativa daquilo que um agente de codificação pode alcançar. Conceda os escopos mais restritos possíveis para que o fluxo de trabalho funcione, mantenha o agente fora de drives compartilhados que ele não tem motivo para acessar, e confirme que existe um registro de auditoria antes de deixá-lo agir sem supervisão. O risco não é tanto a ferramenta se comportar mal, mas sim um agente seguir instruções que encontrou em um documento.</p>
<p>O preço regional também merece atenção: Rs 649 por mês é uma aposta séria em um mercado de desenvolvedores que, em grande parte, ficou fora do alcance das ferramentas de ponta, e para onde a Cursor avançar nessa frente, os concorrentes tendem a seguir.</p>$t$, true);

DELETE FROM news WHERE slug = 'deepseek-v4-flash-0731-price-rise-warning' AND lang = 'es';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('deepseek-v4-flash-0731-price-rise-warning', 'es', 'models', $t$Modelos$t$, '#7c6af7', $t$DeepSeek$t$, '2026-07-31', $t$DeepSeek V4-Flash 0731 llega a $0,14 por millón — con un aviso de que los precios subirán$t$, $t$DeepSeek lanzó la versión 0731 de V4-Flash a $0.14 por millón de tokens de entrada y $0.28 de salida, con una ventana de contexto de 1M y modos de pensamiento y sin pensamiento. Los aciertos de caché cuestan $0.0028 por millón. La documentación de precios incluye un aviso explícito: DeepSeek planea subir los precios de la API, con un aumento significativo previsto.$t$, $t$<p>DeepSeek ha lanzado <strong>V4-Flash versión 0731</strong>, manteniendo la política de precios agresiva por la que se conoce a la línea — y añadiendo una advertencia inusual.</p>
<h2>Las cifras</h2>
<p>V4-Flash cuesta <strong>$0.14 por millón de tokens de entrada en caso de fallo de caché y $0.28 por millón de tokens de salida</strong>. Un acierto de caché reduce el coste de entrada a <strong>$0.0028 por millón</strong> — cincuenta veces más barato, lo que convierte la estructura del prompt en una decisión de coste de primer orden y no en un simple detalle de optimización.</p>
<p>El modelo más grande, <strong>V4-Pro</strong>, se sitúa en $0.435 de entrada y $0.87 de salida por millón, con aciertos de caché a $0.003625. Ambos modelos ofrecen una <strong>ventana de contexto de 1M de tokens</strong> y admiten modos de pensamiento y sin pensamiento.</p>
<h2>La advertencia</h2>
<p>La documentación de precios indica claramente que DeepSeek planea subir el precio general de la API en el futuro próximo, con <strong>un aumento significativo previsto</strong>. Los proveedores rara vez anuncian por adelantado sus propias subidas de precio. Publicarlo implica que las tarifas actuales deben interpretarse como promocionales y no como estructurales.</p>
<h2>Por qué importa</h2>
<p>A $0.14 por millón de entradas, DeepSeek es la opción creíble más barata en el nivel cercano a la frontera, por debajo del recién reducido Luna de OpenAI, a $0.20. Esa diferencia vale algo — pero solo mientras dure, y el proveedor ha dicho que no durará.</p>
<p>La lección práctica tiene que ver con la dependencia del proveedor ("lock-in") más que con el precio. Construir un pipeline de gran volumen alrededor de quien sea más barato este trimestre está bien si los costes de cambio son casi nulos. Resulta caro si la integración es profunda. El descuento por acierto de caché juega en ambos sentidos: diseñar prompts en torno al comportamiento de caché de un proveedor concreto es exactamente el tipo de trabajo que no se traslada a otro.</p>
<h2>Cómo interpretar el precio de la caché</h2>
<p>La diferencia de cincuenta veces entre acierto y fallo de caché es el dato más útil aquí. Significa que la forma del prompt — qué permanece constante entre llamadas y qué varía — determina el coste más que la elección del modelo. Los sistemas que colocan un preámbulo grande y estable al principio y solo varían la parte final obtienen la mayoría de sus tokens de entrada a $0.0028 por millón.</p>
<p>Eso supone dinero real a gran volumen, y también es una forma sutil de dependencia del proveedor: los prompts diseñados en torno al comportamiento de caché de un proveedor no se trasladan de forma limpia a otro.</p>
<h2>Qué prever</h2>
<p>Conviene tratar los precios actuales de DeepSeek como temporales, porque el propio proveedor ha dicho que lo son. Si una carga de trabajo se está dimensionando con estas tarifas, hay que modelar qué ocurre al doble o al triple del precio antes de comprometerse. Un pipeline que solo funciona a $0.14 por millón es un pipeline con cuenta atrás.</p>$t$, true);

DELETE FROM news WHERE slug = 'deepseek-v4-flash-0731-price-rise-warning' AND lang = 'de';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('deepseek-v4-flash-0731-price-rise-warning', 'de', 'models', $t$Modelle$t$, '#7c6af7', $t$DeepSeek$t$, '2026-07-31', $t$DeepSeek V4-Flash 0731 startet mit $0,14 pro Million – und einer Warnung vor steigenden Preisen$t$, $t$DeepSeek hat V4-Flash Version 0731 zu $0,14 pro Million Input-Tokens und $0,28 für Output veröffentlicht, mit einem 1M-Kontextfenster sowie Denk- und Nicht-Denk-Modus. Cache-Treffer kosten $0,0028 pro Million. Die Preisdokumentation enthält eine ausdrückliche Warnung: DeepSeek plant, die API-Preise anzuheben, wobei eine deutliche Erhöhung erwartet wird.$t$, $t$<p>DeepSeek hat <strong>V4-Flash Version 0731</strong> veröffentlicht und behält dabei die aggressive Preisgestaltung bei, für die die Reihe bekannt ist — versehen mit einer ungewöhnlichen Warnung.</p>
<h2>Die Zahlen</h2>
<p>V4-Flash kostet <strong>$0,14 pro Million Input-Tokens bei einem Cache-Miss und $0,28 pro Million Output-Tokens</strong>. Bei einem Cache-Hit sinken die Input-Kosten auf <strong>$0,0028 pro Million</strong> — fünfzigmal günstiger, wodurch die Prompt-Struktur zu einer Kostenentscheidung ersten Ranges wird und nicht bloß zu einem Optimierungsdetail.</p>
<p>Das größere Modell <strong>V4-Pro</strong> liegt bei $0,435 für Input und $0,87 für Output pro Million, mit Cache-Hits zu $0,003625. Beide Modelle bieten ein <strong>1M-Token-Kontextfenster</strong> und unterstützen Denk- und Nicht-Denk-Modi.</p>
<h2>Die Warnung</h2>
<p>Die Preisdokumentation stellt unumwunden fest, dass DeepSeek plant, die allgemeine API-Preisgestaltung in naher Zukunft anzuheben, wobei <strong>eine deutliche Erhöhung erwartet wird</strong>. Anbieter kündigen ihre eigenen Preiserhöhungen selten im Voraus an. Diese Veröffentlichung bedeutet, dass die aktuellen Tarife eher als Werbeaktion denn als dauerhafte Struktur zu verstehen sind.</p>
<h2>Warum das wichtig ist</h2>
<p>Mit $0,14 pro Million Inputs ist DeepSeek die günstigste glaubwürdige Option im Bereich nahe der Spitzenmodelle und unterbietet damit OpenAIs frisch gesenkten Luna-Preis von $0,20. Dieser Abstand ist etwas wert — aber nur solange er anhält, und der Anbieter hat gesagt, dass er nicht von Dauer sein wird.</p>
<p>Die praktische Lehre betrifft eher die Bindung an einen Anbieter als den Preis selbst. Eine Pipeline mit hohem Volumen um denjenigen herum aufzubauen, der in diesem Quartal am billigsten ist, ist unproblematisch, wenn die Wechselkosten nahe null liegen. Teuer wird es, wenn die Integration tief geht. Der Cache-Hit-Rabatt wirkt hier in beide Richtungen: Prompts um das Caching-Verhalten eines bestimmten Anbieters herum zu gestalten, ist genau die Art von Arbeit, die sich nicht übertragen lässt.</p>
<h2>Wie die Cache-Preisgestaltung zu lesen ist</h2>
<p>Die fünfzigfache Differenz zwischen Cache-Hit und Cache-Miss ist die hier am besten umsetzbare Zahl. Sie bedeutet, dass die Form eines Prompts — was über Aufrufe hinweg konstant bleibt und was variiert — die Kosten stärker bestimmt als die Modellwahl. Systeme, die eine große, stabile Präambel voranstellen und nur den Schlussteil variieren, erhalten den Großteil ihrer Input-Tokens zu $0,0028 pro Million.</p>
<p>Das macht bei hohem Volumen echtes Geld aus, und es ist zugleich eine subtile Form der Anbieterbindung: Prompts, die auf das Caching-Verhalten eines bestimmten Anbieters zugeschnitten sind, lassen sich nicht sauber auf einen anderen übertragen.</p>
<h2>Worauf man sich einstellen sollte</h2>
<p>Behandeln Sie die aktuelle DeepSeek-Preisgestaltung als vorübergehend, denn der Anbieter selbst hat das gesagt. Wenn eine Arbeitslast anhand dieser Tarife dimensioniert wird, sollte man vor einer Festlegung durchrechnen, was beim zwei- oder dreifachen Preis passiert. Eine Pipeline, die nur bei $0,14 pro Million funktioniert, ist eine Pipeline mit eingebautem Countdown.</p>$t$, true);

DELETE FROM news WHERE slug = 'deepseek-v4-flash-0731-price-rise-warning' AND lang = 'ru';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('deepseek-v4-flash-0731-price-rise-warning', 'ru', 'models', $t$Модели$t$, '#7c6af7', $t$DeepSeek$t$, '2026-07-31', $t$DeepSeek V4-Flash 0731 вышел по цене $0,14 за миллион токенов — с предупреждением о грядущем росте цен$t$, $t$DeepSeek выпустила версию V4-Flash 0731 по цене $0,14 за миллион входных токенов и $0,28 за выходные, с контекстным окном 1M и режимами с рассуждениями и без них. Обращения к кэшу стоят $0,0028 за миллион. В документации по ценообразованию содержится прямое предупреждение: DeepSeek планирует повысить цены на API, ожидается значительное повышение.$t$, $t$<p>DeepSeek выпустила <strong>V4-Flash версии 0731</strong>, сохранив агрессивное ценообразование, которым известна эта линейка, — и добавив к нему необычное предупреждение.</p>
<h2>Цифры</h2>
<p>V4-Flash стоит <strong>$0,14 за миллион входных токенов при промахе кэша и $0,28 за миллион выходных токенов</strong>. При попадании в кэш стоимость входных токенов падает до <strong>$0,0028 за миллион</strong> — в пятьдесят раз дешевле, что превращает структуру промпта в решение первого порядка по стоимости, а не в деталь оптимизации.</p>
<p>Более крупная модель <strong>V4-Pro</strong> стоит $0,435 за входные и $0,87 за выходные токены за миллион, с попаданием в кэш по $0,003625. Обе модели предлагают <strong>контекстное окно в 1M токенов</strong> и поддерживают режимы с рассуждениями и без них.</p>
<h2>Предупреждение</h2>
<p>В документации по ценообразованию прямо говорится, что DeepSeek планирует в ближайшем будущем повысить общие цены на API, при этом <strong>ожидается значительное повышение</strong>. Поставщики редко заранее анонсируют собственное повышение цен. Публикация такого предупреждения означает, что текущие тарифы следует воспринимать как промоакцию, а не как постоянную структуру.</p>
<h2>Почему это важно</h2>
<p>При цене $0,14 за миллион входных токенов DeepSeek остаётся самым дешёвым надёжным вариантом в категории, близкой к передовым моделям, опережая недавно снижённую цену OpenAI на Luna в $0,20. Эта разница чего-то стоит — но только пока она сохраняется, а поставщик уже заявил, что так будет не всегда.</p>
<p>Практический урок здесь касается не столько цены, сколько привязки к поставщику. Строить высокообъёмный конвейер вокруг того, кто дешевле всего в этом квартале, нормально, если издержки перехода близки к нулю. Это дорого обходится, если интеграция глубокая. Скидка за попадание в кэш работает в обе стороны: проектирование промптов под особенности кэширования одного провайдера — это как раз тот вид работы, который не переносится на другие платформы.</p>
<h2>Как понимать ценообразование кэша</h2>
<p>Пятидесятикратный разрыв между попаданием и промахом кэша — самая практически значимая цифра здесь. Она означает, что форма промпта — что остаётся постоянным между вызовами, а что меняется, — влияет на стоимость сильнее, чем выбор модели. Системы, в которых крупная стабильная преамбула идёт первой, а меняется только хвост, получают большую часть входных токенов по $0,0028 за миллион.</p>
<p>При больших объёмах это реальные деньги, а также тонкая форма привязки к поставщику: промпты, спроектированные под особенности кэширования одного вендора, плохо переносятся на другого.</p>
<h2>К чему готовиться</h2>
<p>Относитесь к текущим ценам DeepSeek как к временным, потому что сам поставщик так и заявил. Если рабочая нагрузка рассчитывается исходя из этих тарифов, смоделируйте, что произойдёт при повышении цены в два-три раза, прежде чем брать на себя обязательства. Конвейер, который работает только при $0,14 за миллион, — это конвейер с обратным отсчётом.</p>$t$, true);

DELETE FROM news WHERE slug = 'deepseek-v4-flash-0731-price-rise-warning' AND lang = 'ua';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('deepseek-v4-flash-0731-price-rise-warning', 'ua', 'models', $t$Моделі$t$, '#7c6af7', $t$DeepSeek$t$, '2026-07-31', $t$DeepSeek V4-Flash 0731 виходить за $0,14 за мільйон — із попередженням про майбутнє підвищення цін$t$, $t$DeepSeek випустила версію V4-Flash 0731 за $0,14 за мільйон вхідних токенів та $0,28 за вихідні, з контекстним вікном 1M та режимами як з міркуванням, так і без нього. Кеш-хіти коштують $0,0028 за мільйон. У документації щодо цін міститься чітке попередження: DeepSeek планує підвищити ціни на API, і очікується суттєве зростання.$t$, $t$<p>DeepSeek випустила <strong>V4-Flash версію 0731</strong>, зберігши агресивну ціну, якою відома ця лінійка — і додавши до неї незвичне попередження.</p>
<h2>Цифри</h2>
<p>V4-Flash коштує <strong>$0,14 за мільйон вхідних токенів у разі кеш-міс та $0,28 за мільйон вихідних токенів</strong>. Кеш-хіт знижує вартість вхідних токенів до <strong>$0,0028 за мільйон</strong> — у п’ятдесят разів дешевше, що робить структуру промпту питанням першого порядку у витратах, а не деталлю оптимізації.</p>
<p>Більша модель <strong>V4-Pro</strong> коштує $0,435 за вхідні та $0,87 за вихідні токени за мільйон, з кеш-хітами по $0,003625. Обидві моделі мають <strong>контекстне вікно 1M токенів</strong> і підтримують режими з міркуванням та без нього.</p>
<h2>Попередження</h2>
<p>У документації щодо цін прямо вказано, що DeepSeek планує в найближчому майбутньому підвищити загальні ціни на API, і <strong>очікується суттєве зростання</strong>. Постачальники рідко наперед оголошують про власне підвищення цін. Публікація цього означає, що поточні тарифи слід сприймати як промоційні, а не структурні.</p>
<h2>Чому це важливо</h2>
<p>За $0,14 за мільйон вхідних токенів DeepSeek є найдешевшим правдоподібним варіантом у категорії, наближеній до передового рівня, обходячи щойно знижений Luna від OpenAI за $0,20. Ця різниця чогось варта — але лише доти, доки вона триває, а постачальник уже заявив, що це триватиме недовго.</p>
<p>Практичний урок стосується прив’язки до постачальника, а не ціни. Будувати високообʼємний конвеєр навколо того, хто наразі найдешевший, добре, якщо витрати на перехід близькі до нуля. Це дорого, якщо інтеграція глибока. Знижка за кеш-хіт тут працює в обидва боки: розробка промптів під поведінку кешування конкретного постачальника — це саме та робота, яка не переноситься на інших.</p>
<h2>Як розуміти ціноутворення кешу</h2>
<p>П’ятдесятикратна різниця між кеш-хітом і кеш-міс — це найпрактичніша цифра тут. Вона означає, що форма промпту — що залишається постійним між викликами, а що змінюється — впливає на вартість більше, ніж вибір моделі. Системи, які спочатку розміщують великий стабільний преамбул і змінюють лише кінцеву частину, отримують більшість вхідних токенів за $0,0028 за мільйон.</p>
<p>Це реальні гроші при великих обсягах, а також прихована форма прив’язки до постачальника: промпти, розроблені під поведінку кешування одного постачальника, не переносяться чисто на іншого.</p>
<h2>Що варто планувати</h2>
<p>Сприймайте поточні ціни DeepSeek як тимчасові, оскільки постачальник сам про це заявив. Якщо навантаження розраховується на основі цих тарифів, промодулюйте, що станеться при подорожчанні в два-три рази, перш ніж брати на себе зобов’язання. Конвеєр, що працює лише за $0,14 за мільйон, — це конвеєр із зворотним відліком.</p>$t$, true);

DELETE FROM news WHERE slug = 'deepseek-v4-flash-0731-price-rise-warning' AND lang = 'he';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('deepseek-v4-flash-0731-price-rise-warning', 'he', 'models', $t$מודלים$t$, '#7c6af7', $t$DeepSeek$t$, '2026-07-31', $t$DeepSeek V4-Flash 0731 יוצא ל-0.14$ למיליון — עם אזהרה שהמחירים יעלו$t$, $t$DeepSeek הוציאה את V4-Flash גרסה 0731 במחיר 0.14$ למיליון טוקני קלט ו-0.28$ לטוקני פלט, עם חלון קונטקסט של 1M וגם מצב חשיבה וגם מצב לא-חשיבה. פגיעות מטמון (cache hits) עולות 0.0028$ למיליון. תיעוד התמחור נושא אזהרה מפורשת: DeepSeek מתכננת להעלות את מחירי ה-API, עם עלייה משמעותית צפויה.$t$, $t$<p>DeepSeek הוציאה את <strong>V4-Flash גרסה 0731</strong>, ושומרת על התמחור התוקפני שהקו הזה מוכר בו — ומצרפת לו אזהרה יוצאת דופן.</p>
<h2>המספרים</h2>
<p>V4-Flash עולה <strong>0.14$ למיליון טוקני קלט בפגיעה מוחמצת במטמון (cache miss) ו-0.28$ למיליון טוקני פלט</strong>. פגיעה במטמון (cache hit) מורידה את עלות הקלט ל-<strong>0.0028$ למיליון</strong> — זול פי חמישים, מה שהופך את מבנה הפרומפט להחלטת עלות מסדר ראשון ולא לפרט אופטימיזציה.</p>
<p>הדגם הגדול יותר, <strong>V4-Pro</strong>, עומד על 0.435$ לקלט ו-0.87$ לפלט למיליון, עם פגיעות מטמון ב-0.003625$. שני הדגמים מציעים <strong>חלון קונטקסט של 1M טוקנים</strong> ותומכים במצבי חשיבה ולא-חשיבה.</p>
<h2>האזהרה</h2>
<p>תיעוד התמחור קובע במפורש כי DeepSeek מתכננת להעלות את תמחור ה-API הכללי בעתיד הקרוב, עם <strong>עלייה משמעותית צפויה</strong>. ספקים לעיתים רחוקות מכריזים מראש על העלאות המחירים שלהם עצמם. פרסום הדבר משמעו שיש לקרוא את התעריפים הנוכחיים כתעריפי מבצע ולא כתעריפים מבניים.</p>
<h2>למה זה חשוב</h2>
<p>ב-0.14$ למיליון טוקני קלט, DeepSeek היא האפשרות האמינה הזולה ביותר בשכבה הקרובה לחוד החזית, ומוזילה מתחת ל-Luna המוזלת טרייה של OpenAI ב-0.20$. הפער הזה שווה משהו — אבל רק כל עוד הוא נמשך, והספק הודיע שהוא לא יימשך.</p>
<p>הלקח המעשי נוגע ליציאה מנעילה (lock-in) יותר מאשר למחיר. בניית צנרת (pipeline) בנפח גבוה סביב מי שהכי זול ברבעון הנוכחי בסדר אם עלויות המעבר קרובות לאפס. זה יקר אם האינטגרציה עמוקה. הנחת פגיעת המטמון פועלת בשני הכיוונים כאן: תכנון פרומפטים סביב התנהגות המטמון של ספק אחד הוא בדיוק סוג העבודה שלא עוברת לספק אחר.</p>
<h2>איך לקרוא את תמחור המטמון</h2>
<p>הפער של פי חמישים בין פגיעה במטמון לפגיעה מוחמצת הוא המספר המעשי ביותר כאן. הוא מלמד שצורת הפרומפט — מה נשאר קבוע בין קריאות ומה משתנה — קובעת את העלות יותר מבחירת הדגם. מערכות ששמות פתיח יציב וגדול בראש ומשנות רק את הזנב מקבלות את רוב טוקני הקלט שלהן ב-0.0028$ למיליון.</p>
<p>זה כסף אמיתי בנפח גבוה, וזו גם צורה עדינה של נעילה: פרומפטים שהונדסו סביב התנהגות המטמון של ספק אחד לא עוברים בצורה חלקה לספק אחר.</p>
<h2>למה להתכונן</h2>
<p>יש להתייחס לתמחור הנוכחי של DeepSeek כזמני, מכיוון שהספק אמר שהוא כזה. אם עומס עבודה מתוכנן בהתבסס על התעריפים האלה, יש למדל מה קורה במחיר כפול או משולש לפני ההתחייבות. צנרת שעובדת רק ב-0.14$ למיליון היא צנרת עם שעון עצר.</p>$t$, true);

DELETE FROM news WHERE slug = 'deepseek-v4-flash-0731-price-rise-warning' AND lang = 'fr';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('deepseek-v4-flash-0731-price-rise-warning', 'fr', 'models', $t$Modèles$t$, '#7c6af7', $t$DeepSeek$t$, '2026-07-31', $t$DeepSeek V4-Flash 0731 débarque à 0,14 $ par million — avec un avertissement sur une hausse des prix à venir$t$, $t$DeepSeek a publié la version 0731 de V4-Flash à 0,14 $ par million de tokens en entrée et 0,28 $ en sortie, avec une fenêtre de contexte de 1M et des modes réflexion et non-réflexion. Les hits de cache coûtent 0,0028 $ par million. La documentation tarifaire comporte un avertissement explicite : DeepSeek prévoit d'augmenter les prix de son API, avec une hausse importante attendue.$t$, $t$<p>DeepSeek a publié <strong>V4-Flash version 0731</strong>, conservant la tarification agressive qui caractérise cette gamme — tout en y associant un avertissement inhabituel.</p>
<h2>Les chiffres</h2>
<p>V4-Flash coûte <strong>0,14 $ par million de tokens en entrée en cas de cache miss et 0,28 $ par million de tokens en sortie</strong>. Un cache hit fait tomber le coût d'entrée à <strong>0,0028 $ par million</strong> — cinquante fois moins cher, ce qui fait de la structure des prompts une décision de coût de premier ordre plutôt qu'un simple détail d'optimisation.</p>
<p>Le modèle plus important <strong>V4-Pro</strong> est à 0,435 $ en entrée et 0,87 $ en sortie par million, avec des cache hits à 0,003625 $. Les deux modèles offrent une <strong>fenêtre de contexte de 1M tokens</strong> et prennent en charge les modes réflexion et non-réflexion.</p>
<h2>L'avertissement</h2>
<p>La documentation tarifaire indique clairement que DeepSeek prévoit d'augmenter globalement les prix de son API dans un futur proche, avec <strong>une hausse importante attendue</strong>. Les fournisseurs annoncent rarement à l'avance leurs propres hausses de prix. Le fait de le publier signifie que les tarifs actuels doivent être considérés comme promotionnels plutôt que structurels.</p>
<h2>Pourquoi cela compte</h2>
<p>À 0,14 $ par million en entrée, DeepSeek est l'option crédible la moins chère dans la catégorie proche de la pointe technologique, se plaçant sous Luna d'OpenAI, récemment réduit à 0,20 $. Cet écart a de la valeur — mais seulement tant qu'il dure, et le fournisseur a annoncé qu'il ne durerait pas.</p>
<p>La leçon pratique porte sur la dépendance plutôt que sur le prix. Construire un pipeline à fort volume autour du fournisseur le moins cher ce trimestre est raisonnable si les coûts de changement sont proches de zéro. C'est coûteux si l'intégration est profonde. La remise sur cache hit joue dans les deux sens ici : concevoir des prompts autour du comportement de cache d'un fournisseur particulier est précisément le genre de travail qui ne se transpose pas ailleurs.</p>
<h2>Comment lire la tarification du cache</h2>
<p>L'écart de cinquante fois entre cache hit et cache miss est le chiffre le plus exploitable ici. Il signifie que la forme d'un prompt — ce qui reste constant d'un appel à l'autre et ce qui varie — pèse davantage sur le coût que le choix du modèle. Les systèmes qui placent d'abord un long préambule stable et ne font varier que la fin obtiennent la majorité de leurs tokens d'entrée à 0,0028 $ par million.</p>
<p>C'est de l'argent réel à volume élevé, et c'est aussi une forme subtile de dépendance : des prompts conçus autour du comportement de cache d'un fournisseur ne se transposent pas facilement chez un autre.</p>
<h2>Ce qu'il faut anticiper</h2>
<p>Considérez la tarification actuelle de DeepSeek comme temporaire, puisque le fournisseur l'a lui-même annoncé. Si une charge de travail est calibrée sur ces tarifs, modélisez ce qui se passerait à deux ou trois fois le prix avant de vous engager. Un pipeline qui ne fonctionne qu'à 0,14 $ par million est un pipeline avec un compte à rebours.</p>$t$, true);

DELETE FROM news WHERE slug = 'deepseek-v4-flash-0731-price-rise-warning' AND lang = 'pt';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('deepseek-v4-flash-0731-price-rise-warning', 'pt', 'models', $t$Modelos$t$, '#7c6af7', $t$DeepSeek$t$, '2026-07-31', $t$DeepSeek V4-Flash 0731 chega a $0,14 por milhão — com aviso de que os preços vão subir$t$, $t$A DeepSeek lançou a versão 0731 do V4-Flash a $0,14 por milhão de tokens de entrada e $0,28 de saída, com janela de contexto de 1M e modos de raciocínio (thinking) e não raciocínio. Acertos de cache custam $0,0028 por milhão. A documentação de preços traz um aviso explícito: a DeepSeek planeja aumentar os preços da API, com um aumento significativo previsto.$t$, $t$<p>A DeepSeek lançou a <strong>versão 0731 do V4-Flash</strong>, mantendo a política de preços agressiva pela qual a linha é conhecida — e acrescentando a ela um aviso pouco comum.</p>
<h2>Os números</h2>
<p>O V4-Flash custa <strong>$0,14 por milhão de tokens de entrada em caso de erro de cache (cache miss) e $0,28 por milhão de tokens de saída</strong>. Um acerto de cache (cache hit) reduz o custo de entrada para <strong>$0,0028 por milhão</strong> — cinquenta vezes mais barato, o que transforma a estrutura do prompt em uma decisão de custo de primeira ordem, e não em um detalhe de otimização.</p>
<p>O modelo maior, <strong>V4-Pro</strong>, custa $0,435 na entrada e $0,87 na saída por milhão, com acertos de cache a $0,003625. Ambos os modelos oferecem uma <strong>janela de contexto de 1M de tokens</strong> e suportam modos de raciocínio (thinking) e não raciocínio.</p>
<h2>O aviso</h2>
<p>A documentação de preços afirma claramente que a DeepSeek planeja aumentar os preços gerais da API em breve, com <strong>um aumento significativo previsto</strong>. É raro que fornecedores anunciem antecipadamente seus próprios aumentos de preço. Publicar isso significa que as tarifas atuais devem ser lidas como promocionais, e não estruturais.</p>
<h2>Por que isso importa</h2>
<p>A $0,14 por milhão de tokens de entrada, a DeepSeek é a opção credível mais barata na categoria próxima da fronteira tecnológica, superando o Luna da OpenAI, recém-reduzido para $0,20. Essa diferença vale alguma coisa — mas só enquanto durar, e o próprio fornecedor já disse que não vai durar.</p>
<p>A lição prática é sobre dependência (lock-in), não sobre preço. Construir um pipeline de alto volume em torno de quem for mais barato neste trimestre é razoável se os custos de troca forem próximos de zero. É caro se a integração for profunda. O desconto por acerto de cache funciona nos dois sentidos aqui: projetar prompts em torno do comportamento de cache de um fornecedor específico é exatamente o tipo de trabalho que não é transferível.</p>
<h2>Como interpretar os preços de cache</h2>
<p>A diferença de cinquenta vezes entre acerto e erro de cache é o número mais aplicável aqui. Isso significa que o formato de um prompt — o que permanece constante entre chamadas e o que varia — determina o custo mais do que a escolha do modelo. Sistemas que colocam um grande preâmbulo estável no início e variam apenas a parte final conseguem a maior parte de seus tokens de entrada a $0,0028 por milhão.</p>
<p>Isso representa dinheiro real em grande volume, e também é uma forma sutil de dependência (lock-in): prompts projetados em torno do comportamento de cache de um fornecedor não se transferem de forma limpa para outro.</p>
<h2>O que planejar</h2>
<p>Trate os preços atuais da DeepSeek como temporários, porque o próprio fornecedor disse que são. Se uma carga de trabalho estiver sendo dimensionada com base nessas tarifas, simule o que acontece com o preço duas ou três vezes maior antes de se comprometer. Um pipeline que só funciona a $0,14 por milhão é um pipeline com um cronômetro correndo contra ele.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-36-flash-ga-sampling-params-deprecated' AND lang = 'es';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-36-flash-ga-sampling-params-deprecated', 'es', 'models', $t$Modelos$t$, '#7c6af7', $t$Google$t$, '2026-07-21', $t$Gemini 3.6 Flash y 3.5 Flash-Lite llegan a disponibilidad general — y Google elimina los parámetros de muestreo$t$, $t$Google llevó gemini-3.6-flash y gemini-3.5-flash-lite a disponibilidad general. 3.6 Flash aporta mayor eficiencia de tokens y una planificación de código y agentes más sólida a un precio más bajo; Flash-Lite está pensado para tareas de subagentes de baja latencia. Ambos llegan con un cambio disruptivo: temperature, top_p y top_k quedan obsoletos para los dos modelos.$t$, $t$<p>Google ha llevado dos modelos a disponibilidad general: <strong>gemini-3.6-flash</strong> y <strong>gemini-3.5-flash-lite</strong>. Ambos son ahora endpoints estables en lugar de versiones preliminares.</p>
<h2>Qué ha cambiado</h2>
<p><strong>Gemini 3.6 Flash</strong> llega con una eficiencia de tokens mejorada y una planificación de código y de agentes más sólida, a un precio más bajo que el modelo al que sustituye. La afirmación sobre la eficiencia de tokens importa más de lo que parece: en ejecuciones agénticas largas, la factura la determina cuántos tokens dedica el modelo a razonar, no el precio por millón que figura en la etiqueta.</p>
<p><strong>Gemini 3.5 Flash-Lite</strong> se posiciona como una opción de subagente de baja latencia y bajo coste: el modelo al que se llama miles de veces dentro de un sistema más grande, en lugar de aquel con el que interactúa directamente el usuario.</p>
<h2>El cambio disruptivo</h2>
<p>Junto con la disponibilidad general llega un cambio que romperá el código existente: <strong>los parámetros de muestreo temperature, top_p y top_k quedan obsoletos para ambos modelos</strong>. El código que los utiliza necesita revisión. Se trata de un giro real de postura: esos tres controles han sido estándar en las API generativas desde el principio, y eliminarlos significa que el modelo decide por sí mismo su comportamiento de muestreo.</p>
<h2>Por qué importa</h2>
<p>Eliminar los controles de muestreo cambia el ajuste por parte del usuario por control del proveedor. Para la mayoría de las aplicaciones los valores predeterminados ya funcionaban bien, y tener menos controles significa menos formas de configurar mal un despliegue. Para los equipos que dedicaron un esfuerzo real a ajustar la temperature según el caso de uso, ese trabajo ahora queda obsoleto.</p>
<p>Cabe destacar la ausencia en este lanzamiento de Gemini 3.5 Pro, que ya ha superado varias ventanas previstas. Google ha lanzado el nivel rápido y económico y ha dejado el modelo insignia para más adelante.</p>
<h2>Qué hacer al respecto</h2>
<p>Audite cualquier ruta de código que establezca temperature, top_p o top_k con estos dos modelos y planifique su eliminación. La obsolescencia no es una eliminación inmediata, pero sí un compromiso, y los parámetros ignorados silenciosamente son peores que los errores: la salida cambia y nada le indica por qué.</p>
<p>Cuando el determinismo realmente importa, el reemplazo es estructural en lugar de paramétrico: restrinja el formato de salida, valide lo que se devuelve y reintente en caso de fallo. Ese enfoque sobrevive a las actualizaciones de modelos de una forma en que un valor de temperature ajustado nunca lo hizo.</p>
<h2>El patrón entre proveedores</h2>
<p>Google no está solo en esto. La industria ha ido eliminando de forma constante los controles de bajo nivel en favor de modelos que gestionan su propio comportamiento de inferencia, y los modelos de razonamiento ya habían vuelto irrelevantes la mayoría de los ajustes de muestreo. Cabe esperar que la superficie de estas API siga reduciéndose.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-36-flash-ga-sampling-params-deprecated' AND lang = 'de';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-36-flash-ga-sampling-params-deprecated', 'de', 'models', $t$Modelle$t$, '#7c6af7', $t$Google$t$, '2026-07-21', $t$Gemini 3.6 Flash und 3.5 Flash-Lite erreichen GA — Google streicht Sampling-Parameter$t$, $t$Google hat gemini-3.6-flash und gemini-3.5-flash-lite in die allgemeine Verfügbarkeit überführt. 3.6 Flash bringt bessere Token-Effizienz sowie stärkere Code- und Agentic-Planungsfähigkeiten zu einem niedrigeren Preis; Flash-Lite ist auf latenzarme Subagent-Aufgaben ausgerichtet. Mit ihnen kommt eine Breaking Change: temperature, top_p und top_k werden für beide Modelle als veraltet eingestuft.$t$, $t$<p>Google hat zwei Modelle in die allgemeine Verfügbarkeit überführt: <strong>gemini-3.6-flash</strong> und <strong>gemini-3.5-flash-lite</strong>. Beide sind nun stabile Endpunkte statt Vorschauversionen.</p>
<h2>Was sich geändert hat</h2>
<p><strong>Gemini 3.6 Flash</strong> kommt mit verbesserter Token-Effizienz sowie besseren Fähigkeiten bei Code und agentischer Planung zu einem niedrigeren Preis als das Modell, das es ersetzt. Die Aussage zur Token-Effizienz ist bedeutsamer, als sie klingt: Bei langen agentischen Abläufen bestimmt sich die Rechnung danach, wie viele Tokens das Modell fürs Nachdenken aufwendet, nicht durch den Preis pro Million auf dem Papier.</p>
<p><strong>Gemini 3.5 Flash-Lite</strong> ist als latenzarme, kosteneffiziente Subagent-Option positioniert — das Modell, das man tausendfach innerhalb eines größeren Systems aufruft, statt jenes, mit dem ein Nutzer direkt spricht.</p>
<h2>Die Breaking Change</h2>
<p>Zusammen mit der GA kommt eine Änderung, die bestehenden Code brechen wird: <strong>Die Sampling-Parameter temperature, top_p und top_k gelten für beide Modelle als veraltet (deprecated)</strong>. Code, der diese übergibt, muss überprüft werden. Das ist ein echter Kurswechsel — diese drei Stellschrauben gehören seit den Anfängen zum Standard generativer APIs, und ihr Wegfall bedeutet, dass das Modell sein eigenes Sampling-Verhalten bestimmt.</p>
<h2>Warum das wichtig ist</h2>
<p>Die Streichung der Sampling-Kontrollen tauscht Nutzer-Feinabstimmung gegen Kontrolle durch den Anbieter. Für die meisten Anwendungen waren die Standardwerte ohnehin schon gut geeignet, und weniger Stellschrauben bedeuten weniger Möglichkeiten, ein Deployment falsch zu konfigurieren. Für Teams, die echten Aufwand in die Feinabstimmung der Temperature je Anwendungsfall gesteckt haben, ist diese Arbeit nun hinfällig.</p>
<p>Auffällig fehlt in diesem Release Gemini 3.5 Pro, das inzwischen mehrere erwartete Zeitfenster verpasst hat. Google hat die schnelle, günstige Stufe ausgeliefert und das Flaggschiff für später zurückgehalten.</p>
<h2>Was zu tun ist</h2>
<p>Prüfen Sie jeden Code-Pfad, der temperature, top_p oder top_k für diese beiden Modelle setzt, und planen Sie dessen Entfernung ein. Deprecation bedeutet keine sofortige Entfernung, ist aber eine Ankündigung — und stillschweigend ignorierte Parameter sind schlimmer als Fehler: Die Ausgabe ändert sich, und nichts sagt einem, warum.</p>
<p>Wo Determinismus wirklich zählt, liegt der Ersatz eher auf struktureller als auf parametrischer Ebene: das Ausgabeformat einschränken, das Ergebnis validieren und bei Fehlschlägen erneut versuchen. Dieser Ansatz übersteht Modell-Upgrades auf eine Weise, wie es ein fein abgestimmter Temperature-Wert nie konnte.</p>
<h2>Das Muster über alle Anbieter hinweg</h2>
<p>Google steht damit nicht allein da. Die Branche entfernt zunehmend Low-Level-Kontrollen zugunsten von Modellen, die ihr eigenes Inferenzverhalten selbst steuern, und Reasoning-Modelle haben ohnehin die meisten Sampling-Anpassungen bedeutungslos gemacht. Es ist zu erwarten, dass die Angriffsfläche dieser APIs weiter schrumpft.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-36-flash-ga-sampling-params-deprecated' AND lang = 'ru';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-36-flash-ga-sampling-params-deprecated', 'ru', 'models', $t$Модели$t$, '#7c6af7', $t$Google$t$, '2026-07-21', $t$Gemini 3.6 Flash и 3.5 Flash-Lite вышли в общий доступ — Google отказывается от параметров выборки$t$, $t$Google перевела gemini-3.6-flash и gemini-3.5-flash-lite в статус общей доступности. 3.6 Flash отличается более эффективным расходом токенов и улучшенным написанием кода и агентным планированием при более низкой цене; Flash-Lite ориентирована на низколатентные подагентные задачи. Вместе с ними вносится обратно несовместимое изменение: параметры temperature, top_p и top_k объявлены устаревшими для обеих моделей.$t$, $t$<p>Google перевела две модели в статус общей доступности: <strong>gemini-3.6-flash</strong> и <strong>gemini-3.5-flash-lite</strong>. Теперь это стабильные эндпоинты, а не превью-версии.</p>
<h2>Что изменилось</h2>
<p><strong>Gemini 3.6 Flash</strong> отличается более эффективным расходом токенов, а также улучшенным написанием кода и агентным планированием при более низкой цене по сравнению с моделью, которую она заменяет. Заявление об эффективности токенов важнее, чем может показаться: при длительных агентных запусках счёт определяется тем, сколько токенов модель тратит на «размышления», а не ценой за миллион токенов на бумаге.</p>
<p><strong>Gemini 3.5 Flash-Lite</strong> позиционируется как низколатентный, экономичный вариант для подагентов — модель, которую вызывают тысячи раз внутри более крупной системы, а не та, с которой напрямую общается пользователь.</p>
<h2>Обратно несовместимое изменение</h2>
<p>Вместе с переходом в общий доступ вносится изменение, которое нарушит работу существующего кода: <strong>параметры выборки temperature, top_p и top_k объявлены устаревшими для обеих моделей</strong>. Код, который передаёт эти параметры, нужно пересмотреть. Это реальный сдвиг в подходе — эти три параметра были стандартом для генеративных API с самого начала, и их удаление означает, что модель сама определяет своё поведение при выборке.</p>
<h2>Почему это важно</h2>
<p>Отказ от контроля выборки означает обмен пользовательской настройки на контроль со стороны вендора. Для большинства приложений настройки по умолчанию и так были приемлемыми, а меньшее число параметров означает меньше способов неправильно настроить развёртывание. Для команд, которые потратили немало усилий на настройку temperature под конкретные сценарии использования, эта работа теперь устарела.</p>
<p>Заметно отсутствует в этом релизе Gemini 3.5 Pro, выход которой уже несколько раз откладывался сверх ожидаемых сроков. Google выпустила быстрый и дешёвый уровень моделей, оставив флагман на потом.</p>
<h2>Что делать</h2>
<p>Проверьте весь код, который задаёт temperature, top_p или top_k для этих двух моделей, и запланируйте его удаление. Устаревание параметра — это не немедленное удаление, но это обязательство, а незаметно игнорируемые параметры хуже, чем явные ошибки: вывод меняется, а причина остаётся неясной.</p>
<p>Там, где детерминированность действительно важна, замена должна быть структурной, а не параметрической: ограничьте формат вывода, проверяйте то, что возвращается, и повторяйте запрос при неудаче. Такой подход переживает обновления моделей так, как никогда не переживало подобранное значение temperature.</p>
<h2>Общая тенденция среди вендоров</h2>
<p>Google здесь не одинока. Индустрия постепенно отказывается от низкоуровневых настроек в пользу моделей, которые сами управляют своим поведением при инференсе, а reasoning-модели в любом случае сделали большинство настроек выборки бессмысленными. Стоит ожидать, что площадь поверхности этих API продолжит сокращаться.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-36-flash-ga-sampling-params-deprecated' AND lang = 'ua';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-36-flash-ga-sampling-params-deprecated', 'ua', 'models', $t$Моделі$t$, '#7c6af7', $t$Google$t$, '2026-07-21', $t$Gemini 3.6 Flash і 3.5 Flash-Lite отримали статус GA — Google відмовляється від параметрів вибірки$t$, $t$Google перевела gemini-3.6-flash і gemini-3.5-flash-lite у статус загальної доступності (general availability). 3.6 Flash пропонує кращу ефективність токенів і потужніше кодування та агентне планування за нижчою ціною; Flash-Lite орієнтований на низьколатентну роботу субагентів. Разом з ними з'являється й «зламна» зміна: параметри temperature, top_p і top_k визнано застарілими для обох моделей.$t$, $t$<p>Google перевела дві моделі у статус загальної доступності: <strong>gemini-3.6-flash</strong> і <strong>gemini-3.5-flash-lite</strong>. Тепер це стабільні кінцеві точки, а не попередні версії.</p>
<h2>Що змінилося</h2>
<p><strong>Gemini 3.6 Flash</strong> постачається з поліпшеною ефективністю токенів і кращим кодуванням та агентним плануванням за нижчою ціною порівняно з моделлю, яку вона замінює. Твердження про ефективність токенів важливіше, ніж може здатися: під час довгих агентних запусків рахунок визначається тим, скільки токенів модель витрачає на «мислення», а не ціною за мільйон токенів.</p>
<p><strong>Gemini 3.5 Flash-Lite</strong> позиціонується як низьколатентний, економічний варіант для субагентів — модель, яку викликають тисячі разів усередині більшої системи, а не та, з якою спілкується користувач.</p>
<h2>«Зламна» зміна</h2>
<p>Разом із GA з'являється зміна, яка порушить наявний код: <strong>параметри вибірки temperature, top_p і top_k визнано застарілими для обох моделей</strong>. Код, який їх передає, потребує перевірки. Це справжня зміна підходу — ці три параметри були стандартом для генеративних API з самого початку, і їх видалення означає, що модель сама вирішує, як поводитися під час вибірки.</p>
<h2>Чому це важливо</h2>
<p>Відмова від контролю за вибіркою обмінює налаштування користувача на контроль постачальника. Для більшості застосунків стандартні значення й так були прийнятними, а менша кількість параметрів означає менше способів неправильно налаштувати розгортання. Для команд, які витратили реальні зусилля на налаштування temperature під конкретний випадок використання, ця робота тепер втрачає сенс.</p>
<p>Помітно відсутньою в цьому релізі є Gemini 3.5 Pro, вихід якої вже кілька разів переносили попри очікувані терміни. Google випустила швидкий, дешевий рівень, а флагман залишила на потім.</p>
<h2>Що з цим робити</h2>
<p>Перевірте будь-який фрагмент коду, який встановлює temperature, top_p або top_k для цих двох моделей, і плануйте його видалення. Застарілий статус не означає негайне видалення, але це зобов'язання, а мовчазно ігноровані параметри гірші за помилки — результат змінюється, і ніщо не підказує, чому.</p>
<p>Там, де детермінізм справді важливий, заміна має структурний, а не параметричний характер: обмежуйте формат виведення, перевіряйте отримані результати та повторюйте спробу у разі невдачі. Такий підхід переживає оновлення моделей так, як налаштоване значення temperature ніколи не могло.</p>
<h2>Тенденція серед постачальників</h2>
<p>Google тут не самотня. Індустрія поступово відмовляється від низькорівневих елементів керування на користь моделей, які самі керують своєю поведінкою під час інференсу, а моделі з міркуванням у будь-якому разі зробили більшість налаштувань вибірки безглуздими. Слід очікувати, що поверхня цих API продовжуватиме звужуватися.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-36-flash-ga-sampling-params-deprecated' AND lang = 'he';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-36-flash-ga-sampling-params-deprecated', 'he', 'models', $t$מודלים$t$, '#7c6af7', $t$Google$t$, '2026-07-21', $t$Gemini 3.6 Flash ו-3.5 Flash-Lite עוברים לזמינות כללית — וגוגל מבטלת את פרמטרי הדגימה$t$, $t$גוגל העבירה את gemini-3.6-flash ואת gemini-3.5-flash-lite לזמינות כללית. 3.6 Flash מביא יעילות טוקנים משופרת ותכנון קוד וסוכנים חזק יותר במחיר נמוך יותר; Flash-Lite מיועד לעבודת תת-סוכנים בהשהיה נמוכה. יחד איתם מגיע שינוי שובר תאימות: הפרמטרים temperature, top_p ו-top_k מוצאים משימוש (deprecated) עבור שני המודלים.$t$, $t$<p>גוגל העבירה שני מודלים לזמינות כללית: <strong>gemini-3.6-flash</strong> ו-<strong>gemini-3.5-flash-lite</strong>. שניהם הם כעת נקודות קצה (endpoints) יציבות ולא גרסאות תצוגה מקדימה.</p>
<h2>מה השתנה</h2>
<p><strong>Gemini 3.6 Flash</strong> מגיע עם יעילות טוקנים משופרת ותכנון קוד וסוכנים טוב יותר, במחיר נמוך יותר מהמודל שהוא מחליף. הטענה לגבי יעילות הטוקנים חשובה יותר משהיא נשמעת: בהרצות סוכנים ארוכות, העלות נקבעת לפי כמות הטוקנים שהמודל מבזבז על חשיבה, לא לפי המחיר הרשמי למיליון טוקנים.</p>
<p><strong>Gemini 3.5 Flash-Lite</strong> ממוצב כאפשרות תת-סוכן (subagent) בהשהיה נמוכה וחסכונית מבחינת עלות — המודל שקוראים לו אלפי פעמים בתוך מערכת גדולה יותר, ולא זה שמשתמש מדבר איתו ישירות.</p>
<h2>השינוי שובר התאימות</h2>
<p>יחד עם הזמינות הכללית מגיע שינוי שישבור קוד קיים: <strong>הפרמטרים לדגימה temperature, top_p ו-top_k מוצאים משימוש (deprecated) עבור שני המודלים</strong>. קוד שמעביר אותם דורש בדיקה מחדש. זהו שינוי מהותי בגישה — שלושת הכפתורים הללו היו סטנדרטיים בממשקי API יצירתיים מאז ומתמיד, וההסרה שלהם משמעה שהמודל עצמו קובע את התנהגות הדגימה שלו.</p>
<h2>למה זה חשוב</h2>
<p>ביטול פקדי הדגימה מחליף כוונון מצד המשתמש בשליטה מצד הספק. עבור רוב היישומים ברירות המחדל היו טובות ממילא, ופחות כפתורים משמעו פחות דרכים להגדיר פריסה בצורה שגויה. עבור צוותים שהשקיעו מאמץ אמיתי בכוונון temperature לכל מקרה שימוש, העבודה הזו הופכת כעת ללא רלוונטית.</p>
<p>נעדר באופן בולט מהשחרור הזה הוא Gemini 3.5 Pro, שכבר החמיץ כמה חלונות זמן צפויים. גוגל שחררה את הדרג המהיר והזול והשאירה את הדגל למועד מאוחר יותר.</p>
<h2>מה לעשות בנידון</h2>
<p>יש לבדוק כל נתיב קוד שמגדיר temperature, top_p או top_k מול שני המודלים הללו ולתכנן את הסרתם. הוצאה משימוש (deprecation) אינה הסרה מיידית, אך היא מהווה התחייבות, ופרמטרים שמתעלמים מהם בשקט גרועים יותר משגיאות — הפלט משתנה ושום דבר לא מסביר למה.</p>
<p>במקומות שבהם דטרמיניזם באמת חשוב, התחליף הוא מבני ולא פרמטרי: להגביל את פורמט הפלט, לאמת את מה שחוזר, ולנסות שוב במקרה של כשל. הגישה הזו שורדת שדרוגי מודלים בצורה שערך temperature מכוון מעולם לא שרד.</p>
<h2>הדפוס בין הספקים</h2>
<p>גוגל אינה לבד בכך. התעשייה כולה מסירה בהדרגה פקדים ברמה נמוכה לטובת מודלים שמנהלים בעצמם את התנהגות ההיסק שלהם, ומודלי חשיבה (reasoning models) כבר הפכו את רוב כוונוני הדגימה לחסרי משמעות ממילא. יש לצפות שהיקף הממשקים (API) הללו ימשיך להצטמצם.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-36-flash-ga-sampling-params-deprecated' AND lang = 'fr';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-36-flash-ga-sampling-params-deprecated', 'fr', 'models', $t$Modèles$t$, '#7c6af7', $t$Google$t$, '2026-07-21', $t$Gemini 3.6 Flash et 3.5 Flash-Lite passent en disponibilité générale — Google supprime les paramètres d'échantillonnage$t$, $t$Google a fait passer gemini-3.6-flash et gemini-3.5-flash-lite en disponibilité générale. 3.6 Flash apporte une meilleure efficacité en tokens et des capacités renforcées en code et en planification agentique, à un prix inférieur ; Flash-Lite vise les tâches de sous-agents à faible latence. Ces sorties s'accompagnent d'un changement majeur : temperature, top_p et top_k sont dépréciés pour les deux modèles.$t$, $t$<p>Google a fait passer deux modèles en disponibilité générale : <strong>gemini-3.6-flash</strong> et <strong>gemini-3.5-flash-lite</strong>. Les deux sont désormais des points d'accès stables, et non plus des versions preview.</p>
<h2>Ce qui change</h2>
<p><strong>Gemini 3.6 Flash</strong> apporte une meilleure efficacité en tokens ainsi que des capacités renforcées en code et en planification agentique, à un prix inférieur à celui du modèle qu'il remplace. Cette amélioration de l'efficacité en tokens compte plus qu'il n'y paraît : sur des exécutions agentiques longues, la facture dépend du nombre de tokens que le modèle consacre à « réfléchir », et non du prix affiché par million de tokens.</p>
<p><strong>Gemini 3.5 Flash-Lite</strong> se positionne comme une option de sous-agent à faible latence et économique — le modèle que l'on appelle des milliers de fois au sein d'un système plus large, plutôt que celui auquel un utilisateur s'adresse directement.</p>
<h2>Le changement majeur</h2>
<p>Cette disponibilité générale s'accompagne d'un changement susceptible de casser du code existant : <strong>les paramètres d'échantillonnage temperature, top_p et top_k sont dépréciés pour les deux modèles</strong>. Tout code qui les utilise doit être révisé. Il s'agit d'un véritable changement de posture — ces trois réglages sont des standards des API génératives depuis leurs débuts, et leur suppression signifie que le modèle décide désormais lui-même de son comportement d'échantillonnage.</p>
<h2>Pourquoi c'est important</h2>
<p>Déprécier les contrôles d'échantillonnage revient à échanger la personnalisation utilisateur contre un contrôle accru du fournisseur. Pour la plupart des applications, les réglages par défaut convenaient déjà, et moins de réglages signifie moins de façons de mal configurer un déploiement. Pour les équipes qui avaient consacré un réel effort à ajuster la temperature selon leurs cas d'usage, ce travail est désormais obsolète.</p>
<p>Notable absent de cette sortie : Gemini 3.5 Pro, dont l'arrivée a maintenant dépassé plusieurs fenêtres attendues. Google a livré le niveau rapide et économique, laissant le modèle phare pour plus tard.</p>
<h2>Que faire</h2>
<p>Auditez tout chemin de code définissant temperature, top_p ou top_k pour ces deux modèles et prévoyez de le supprimer. Une dépréciation n'est pas une suppression immédiate, mais elle constitue un engagement, et des paramètres ignorés silencieusement sont pires que des erreurs explicites — la sortie change sans qu'aucune indication n'explique pourquoi.</p>
<p>Là où le déterminisme compte réellement, la solution de remplacement est structurelle plutôt que paramétrique : contraindre le format de sortie, valider ce qui est renvoyé, et relancer en cas d'échec. Cette approche résiste aux montées de version des modèles, contrairement à une valeur de temperature ajustée manuellement.</p>
<h2>Une tendance commune aux fournisseurs</h2>
<p>Google n'est pas seul dans cette démarche. Le secteur supprime progressivement les contrôles de bas niveau au profit de modèles qui gèrent eux-mêmes leur comportement d'inférence, et les modèles de raisonnement ont de toute façon rendu la plupart des ajustements d'échantillonnage sans grand effet. Il faut s'attendre à ce que la surface fonctionnelle de ces API continue de se réduire.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-36-flash-ga-sampling-params-deprecated' AND lang = 'pt';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-36-flash-ga-sampling-params-deprecated', 'pt', 'models', $t$Modelos$t$, '#7c6af7', $t$Google$t$, '2026-07-21', $t$Gemini 3.6 Flash e 3.5 Flash-Lite chegam à disponibilidade geral — e Google descontinua parâmetros de amostragem$t$, $t$O Google levou o gemini-3.6-flash e o gemini-3.5-flash-lite à disponibilidade geral. O 3.6 Flash traz melhor eficiência de tokens e planejamento de código e agentic mais forte a um preço mais baixo; o Flash-Lite é voltado para trabalho de subagentes com baixa latência. Uma mudança que quebra compatibilidade acompanha o lançamento: temperature, top_p e top_k foram descontinuados para ambos os modelos.$t$, $t$<p>O Google levou dois modelos à disponibilidade geral: <strong>gemini-3.6-flash</strong> e <strong>gemini-3.5-flash-lite</strong>. Ambos agora são endpoints estáveis, e não mais previews.</p>
<h2>O que mudou</h2>
<p>O <strong>Gemini 3.6 Flash</strong> chega com eficiência de tokens aprimorada e melhor planejamento de código e agentic a um preço mais baixo do que o modelo que substitui. A afirmação sobre eficiência de tokens importa mais do que parece: em execuções agentic longas, a conta é determinada pela quantidade de tokens que o modelo gasta pensando, não pelo preço nominal por milhão.</p>
<p>O <strong>Gemini 3.5 Flash-Lite</strong> é posicionado como uma opção de subagente com baixa latência e custo eficiente — o modelo que você chama milhares de vezes dentro de um sistema maior, e não aquele com o qual o usuário conversa.</p>
<h2>A mudança que quebra compatibilidade</h2>
<p>Junto com a disponibilidade geral vem uma mudança que vai quebrar código existente: <strong>os parâmetros de amostragem temperature, top_p e top_k foram descontinuados para ambos os modelos</strong>. Código que os utiliza precisa ser revisado. Trata-se de uma mudança real de postura — esses três controles têm sido padrão em APIs generativas desde o início, e removê-los significa que o modelo decide seu próprio comportamento de amostragem.</p>
<h2>Por que isso importa</h2>
<p>Descontinuar os controles de amostragem troca o ajuste feito pelo usuário por controle do fornecedor. Para a maioria das aplicações, os valores padrão já eram suficientes, e menos controles significam menos formas de configurar mal uma implantação. Para equipes que investiram esforço real ajustando temperature para cada caso de uso, esse trabalho agora está obsoleto.</p>
<p>Notavelmente ausente deste lançamento é o Gemini 3.5 Pro, que já passou de várias janelas esperadas. O Google lançou o nível rápido e barato e deixou o modelo principal para depois.</p>
<h2>O que fazer a respeito</h2>
<p>Auditar qualquer trecho de código que defina temperature, top_p ou top_k para esses dois modelos e planejar sua remoção. Descontinuação não é remoção imediata, mas é um compromisso, e parâmetros silenciosamente ignorados são piores do que erros — a saída muda e nada indica o motivo.</p>
<p>Onde o determinismo realmente importa, a substituição é estrutural, e não paramétrica: restrinja o formato de saída, valide o que retorna e tente novamente em caso de falha. Essa abordagem sobrevive a atualizações de modelo de um jeito que um valor de temperature ajustado nunca sobreviveu.</p>
<h2>O padrão entre fornecedores</h2>
<p>O Google não está sozinho nisso. A indústria vem removendo constantemente controles de baixo nível em favor de modelos que gerenciam seu próprio comportamento de inferência, e os modelos de raciocínio já tornaram a maioria dos ajustes de amostragem irrelevantes de qualquer forma. É esperado que a superfície dessas APIs continue diminuindo.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-robotics-er-2-public-preview' AND lang = 'es';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-robotics-er-2-public-preview', 'es', 'models', $t$Modelos$t$, '#7c6af7', $t$Google$t$, '2026-07-30', $t$Gemini Robotics ER 2 entra en vista previa pública con coordinación multi-robot$t$, $t$Google abrió la vista previa pública de Gemini Robotics ER 2 con dos endpoints: gemini-robotics-er-2-preview para razonamiento espacial avanzado y coordinación multi-robot, y una variante en streaming optimizada para uso en tiempo real a través de la Live API. La generación anterior, gemini-robotics-er-1.6-preview, se cerrará el 31 de agosto de 2026.$t$, $t$<p>Google ha abierto la <strong>vista previa pública de Gemini Robotics ER 2</strong>, la línea de razonamiento corporeizado orientada a la robótica y no al chat.</p>
<h2>Qué se lanzó</h2>
<p>Hay dos endpoints disponibles. <strong>gemini-robotics-er-2-preview</strong> se encarga del razonamiento espacial avanzado y la <strong>coordinación multi-robot</strong>: planificar entre varias máquinas que trabajan en el mismo espacio en lugar de dirigir una sola de forma aislada. <strong>gemini-robotics-er-2-streaming-preview</strong> está optimizado para la transmisión de texto en tiempo real a través de la Live API, para casos en los que un robot no puede esperar una respuesta completa antes de actuar.</p>
<h2>Fecha límite de migración</h2>
<p>La generación anterior, <strong>gemini-robotics-er-1.6-preview, se cerrará el 31 de agosto de 2026</strong>. Quien esté construyendo sobre 1.6 tiene una fecha límite firme para migrar. Los endpoints en vista previa no ofrecen garantía de estabilidad, y esto es un recordatorio de lo que eso significa en la práctica.</p>
<h2>Por qué importa</h2>
<p>La coordinación multi-robot es la parte interesante. La manipulación con un solo brazo es un problema lo bastante resuelto como para que la frontera se haya desplazado hacia máquinas que comparten un espacio de trabajo y deben razonar unas respecto de las otras. Esa es la diferencia entre una demostración y un almacén.</p>
<p>El endpoint de streaming apunta al mismo cambio. La robótica tiene un margen de latencia que el chat no tiene: una respuesta que llega después de que el momento ha pasado es peor que ninguna respuesta. Construir una vía de streaming dedicada sugiere que la restricción se está tomando en serio y no se está disimulando.</p>
<p>Esto sigue siendo software en vista previa, con una discontinuación ya programada para su predecesor. Útil para evaluación, no algo sobre lo que construir todavía una línea de producción.</p>
<h2>Leyendo la discontinuación</h2>
<p>El cierre de ER 1.6 el 31 de agosto, que coincide con el mismo día de la vista previa de ER 2, merece atención por sí solo. Alrededor de un mes de solapamiento es una ventana de migración corta para trabajos de robótica, donde los cambios deben validarse contra hardware físico y no contra una suite de pruebas.</p>
<p>Quien esté evaluando esta línea debería asumir que el mismo ritmo se aplicará en adelante y presupuestarlo. Los endpoints en vista previa en robótica conllevan un costo que los endpoints en vista previa en chat no tienen: el trabajo de integración reside en parte en la configuración física, y eso no se traslada automáticamente.</p>
<h2>Dónde encaja</h2>
<p>Para la mayor parte de nuestra audiencia esto es contexto y no una herramienta para adoptar hoy. Importa porque el razonamiento corporeizado es donde los grandes laboratorios están invirtiendo a continuación, y las capacidades aparecen en productos adyacentes: las mejoras en razonamiento espacial se manifiestan en la comprensión de video y el control de pantalla mucho antes de que se manifiesten en un almacén.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-robotics-er-2-public-preview' AND lang = 'de';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-robotics-er-2-public-preview', 'de', 'models', $t$Modelle$t$, '#7c6af7', $t$Google$t$, '2026-07-30', $t$Gemini Robotics ER 2 startet in die öffentliche Vorschau mit Multi-Roboter-Koordination$t$, $t$Google hat die öffentliche Vorschau für Gemini Robotics ER 2 mit zwei Endpunkten gestartet: gemini-robotics-er-2-preview für fortgeschrittenes räumliches Denken und Multi-Roboter-Koordination sowie eine Streaming-Variante, die für Echtzeit-Einsatz über die Live API optimiert ist. Die vorherige Generation, gemini-robotics-er-1.6-preview, wird am 31. August 2026 abgeschaltet.$t$, $t$<p>Google hat die <strong>öffentliche Vorschau für Gemini Robotics ER 2</strong> gestartet, die Linie für verkörpertes Denken (Embodied Reasoning), die auf Robotik statt auf Chat ausgerichtet ist.</p>
<h2>Was veröffentlicht wurde</h2>
<p>Zwei Endpunkte sind verfügbar. <strong>gemini-robotics-er-2-preview</strong> übernimmt fortgeschrittenes räumliches Denken und <strong>Multi-Roboter-Koordination</strong> — Planung über mehrere Maschinen hinweg, die im selben Raum arbeiten, statt nur eine isoliert zu steuern. <strong>gemini-robotics-er-2-streaming-preview</strong> ist für Echtzeit-Textstreaming über die Live API optimiert, für Fälle, in denen ein Roboter nicht auf eine vollständige Antwort warten kann, bevor er handelt.</p>
<h2>Frist für die Migration</h2>
<p>Die vorherige Generation, <strong>gemini-robotics-er-1.6-preview, wird am 31. August 2026 abgeschaltet</strong>. Wer auf 1.6 aufbaut, hat damit ein festes Datum für den Umstieg. Vorschau-Endpunkte bieten keine Stabilitätsgarantie, und das ist eine Erinnerung daran, was das in der Praxis bedeutet.</p>
<h2>Warum es wichtig ist</h2>
<p>Die Multi-Roboter-Koordination ist der interessante Teil. Manipulation mit einem einzelnen Arm ist ein hinreichend gelöstes Problem, sodass sich die Grenze zu Maschinen verschoben hat, die sich einen Arbeitsbereich teilen und einander mitdenken müssen. Das ist der Unterschied zwischen einer Demo und einem Lagerhaus.</p>
<p>Der Streaming-Endpunkt deutet auf denselben Wandel hin. Robotik hat ein Latenzbudget, das Chat nicht hat — eine Antwort, die nach dem entscheidenden Moment eintrifft, ist schlechter als keine Antwort. Einen eigenen Streaming-Pfad zu bauen, deutet darauf hin, dass diese Einschränkung ernst genommen und nicht nur überdeckt wird.</p>
<p>Es handelt sich weiterhin um Vorschau-Software, deren Vorgänger bereits einen geplanten Abschaltungstermin hat. Nützlich zur Evaluierung, aber noch nicht etwas, auf dem man eine Produktionslinie aufbauen sollte.</p>
<h2>Die Abschaltung einordnen</h2>
<p>Dass die Abschaltung von ER 1.6 am 31. August mit der Vorschau von ER 2 am selben Tag zusammenfällt, ist an sich bemerkenswert. Rund ein Monat Überlappung ist ein kurzes Migrationsfenster für Robotik-Arbeit, bei der Änderungen an physischer Hardware validiert werden müssen und nicht nur an einer Testsuite.</p>
<p>Wer diese Linie evaluiert, sollte davon ausgehen, dass dasselbe Tempo auch künftig gilt, und dies entsprechend einplanen. Vorschau-Endpunkte in der Robotik verursachen einen Aufwand, den Vorschau-Endpunkte im Chat nicht haben: Die Integrationsarbeit liegt teilweise im physischen Aufbau, und das lässt sich nicht automatisch übertragen.</p>
<h2>Wo es einzuordnen ist</h2>
<p>Für den Großteil unseres Publikums ist dies eher Kontext als ein Werkzeug, das man heute einsetzen sollte. Es ist deshalb relevant, weil verkörpertes Denken der Bereich ist, in den die großen Labore als Nächstes investieren, und die Fähigkeiten tauchen in angrenzenden Produkten auf — Verbesserungen im räumlichen Denken zeigen sich im Video-Verständnis und in der Bildschirmsteuerung, lange bevor sie in einem Lagerhaus ankommen.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-robotics-er-2-public-preview' AND lang = 'ua';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-robotics-er-2-public-preview', 'ua', 'models', $t$Моделі$t$, '#7c6af7', $t$Google$t$, '2026-07-30', $t$Gemini Robotics ER 2 виходить у публічний перегляд з підтримкою координації кількох роботів$t$, $t$Google відкрила публічний перегляд Gemini Robotics ER 2 з двома точками доступу: gemini-robotics-er-2-preview для розширеного просторового міркування та координації кількох роботів, а також потоковий варіант, оптимізований для роботи в реальному часі через Live API. Попереднє поколінняGemini gemini-robotics-er-1.6-preview буде відключене 31 серпня 2026 року.$t$, $t$<p>Google відкрила <strong>публічний перегляд Gemini Robotics ER 2</strong> — лінійки для втіленого міркування (embodied reasoning), орієнтованої на робототехніку, а не на чат.</p>
<h2>Що вийшло</h2>
<p>Доступні дві точки доступу. <strong>gemini-robotics-er-2-preview</strong> відповідає за розширене просторове міркування та <strong>координацію кількох роботів</strong> — планування дій одразу для кількох машин, що працюють у спільному просторі, а не керування однією машиною окремо. <strong>gemini-robotics-er-2-streaming-preview</strong> оптимізований для потокової передачі тексту в реальному часі через Live API — для випадків, коли робот не може чекати повної відповіді, перш ніж діяти.</p>
<h2>Дедлайн переходу</h2>
<p>Попереднє поколінняGemini, <strong>gemini-robotics-er-1.6-preview, буде відключене 31 серпня 2026 року</strong>. Усі, хто розробляє на базі 1.6, мають чітку дату для переходу. Preview-точки доступу не мають гарантій стабільності, і це нагадування про те, що це означає на практиці.</p>
<h2>Чому це важливо</h2>
<p>Координація кількох роботів — найцікавіша частина. Маніпуляція однією рукою-маніпулятором є вже достатньо вирішеною задачею, тож передовий край перемістився до машин, які поділяють робочий простір і мають враховувати одна одну. Це і є різниця між демонстрацією та складом.</p>
<p>Потокова точка доступу вказує на той самий зсув. Робототехніка має бюджет затримки, якого немає в чаті — відповідь, що надходить після того, як момент минув, гірша, ніж відсутність відповіді. Створення окремого потокового шляху свідчить про те, що це обмеження сприймають серйозно, а не замовчують.</p>
<p>Це залишається програмним забезпеченням у стані попереднього перегляду, для попередника якого вже запланована відмова від підтримки. Корисно для оцінки, але поки не варто будувати на цьому виробничу лінію.</p>
<h2>Як читати відмову від підтримки</h2>
<p>Той факт, що відключення ER 1.6 31 серпня збігається з тим самим днем, коли виходить попередній перегляд ER 2, варте окремої уваги. Приблизно місяць перекриття — це короткий вікно для переходу в роботі з робототехнікою, де зміни потрібно перевіряти на фізичному обладнанні, а не лише в тестовому наборі.</p>
<p>Усі, хто оцінює цю лінійку, повинні припускати, що такий самий темп застосовуватиметься і надалі, і закладати це в плани. Preview-точки доступу в робототехніці несуть витрати, яких немає у preview-точок доступу в чаті: частина інтеграційної роботи припадає на фізичне налаштування, а це не переноситься автоматично.</p>
<h2>Де це має значення</h2>
<p>Для більшості нашої аудиторії це швидше контекст, ніж інструмент для впровадження вже сьогодні. Це важливо, бо втілене міркування — саме те, куди великі лабораторії спрямовують подальші зусилля, а можливості з'являються й у суміжних продуктах — покращення просторового міркування проявляються в розумінні відео та керуванні екраном задовго до того, як вони проявляться на складі.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-robotics-er-2-public-preview' AND lang = 'he';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-robotics-er-2-public-preview', 'he', 'models', $t$מודלים$t$, '#7c6af7', $t$Google$t$, '2026-07-30', $t$Gemini Robotics ER 2 נכנס לתצוגה מקדימה פומבית עם תיאום בין רובוטים מרובים$t$, $t$גוגל פתחה תצוגה מקדימה פומבית ל-Gemini Robotics ER 2 עם שתי נקודות קצה: gemini-robotics-er-2-preview לחשיבה מרחבית מתקדמת ותיאום בין רובוטים מרובים, וגרסת סטרימינג המותאמת לשימוש בזמן אמת דרך Live API. הגרסה הקודמת, gemini-robotics-er-1.6-preview, תיסגר ב-31 באוגוסט 2026.$t$, $t$<p>גוגל פתחה <strong>תצוגה מקדימה פומבית ל-Gemini Robotics ER 2</strong>, קו המוצרים לחשיבה מגולמת (embodied reasoning) המיועד לרובוטיקה ולא לצ'אט.</p>
<h2>מה יצא לדרך</h2>
<p>שתי נקודות קצה זמינות. <strong>gemini-robotics-er-2-preview</strong> מטפלת בחשיבה מרחבית מתקדמת וב<strong>תיאום בין רובוטים מרובים</strong> — תכנון עבור כמה מכונות הפועלות באותו מרחב, ולא הפעלה של מכונה בודדת בנפרד. <strong>gemini-robotics-er-2-streaming-preview</strong> מותאמת לזרימת טקסט בזמן אמת דרך Live API, למקרים בהם רובוט לא יכול להמתין לתגובה מלאה לפני שהוא פועל.</p>
<h2>מועד אחרון למעבר</h2>
<p>הגרסה הקודמת, <strong>gemini-robotics-er-1.6-preview, תיסגר ב-31 באוגוסט 2026</strong>. כל מי שבונה על 1.6 מקבל תאריך קשיח לעבור עד אליו. נקודות קצה בתצוגה מקדימה אינן כרוכות בהתחייבות ליציבות, וזה תזכורת למה שזה אומר בפועל.</p>
<h2>למה זה חשוב</h2>
<p>תיאום בין רובוטים מרובים הוא החלק המעניין. מניפולציה עם זרוע בודדת היא בעיה שנפתרה במידה מספקת, כך שהחזית עברה למכונות שחולקות סביבת עבודה ונדרשות לחשוב אחת על השנייה. זה ההבדל בין הדגמה למחסן פעיל.</p>
<p>נקודת הקצה לסטרימינג מצביעה על אותו שינוי. לרובוטיקה יש תקציב זמן תגובה (latency) שאין לצ'אט — תגובה שמגיעה אחרי שהרגע עבר גרועה מאי-תגובה. בניית נתיב סטרימינג ייעודי מרמזת שהאילוץ הזה נלקח בכובד ראש ולא נדחק לפינה.</p>
<p>זו עדיין תוכנת תצוגה מקדימה, עם הפסקת תמיכה שנקבעה כבר לגרסה הקודמת שלה. שימושית להערכה, לא דבר שבונים עליו קו ייצור בשלב הזה.</p>
<h2>קריאה של הפסקת התמיכה</h2>
<p>העובדה שסגירת ER 1.6 ב-31 באוגוסט חופפת ליום שבו נפתחה התצוגה המקדימה של ER 2 היא עצמה שווה תשומת לב. חפיפה של כחודש היא חלון מעבר קצר לעבודת רובוטיקה, שבה שינויים חייבים להיות מאומתים על ציוד פיזי ולא רק על סוויטת בדיקות.</p>
<p>כל מי שמעריך את קו המוצרים הזה צריך להניח שאותו קצב יחול גם בהמשך ולתקצב בהתאם. נקודות קצה בתצוגה מקדימה ברובוטיקה טומנות עלות שאין לה מקביל בעולם הצ'אט: עבודת האינטגרציה נמצאת בחלקה בהתקנה הפיזית, וזו לא עוברת אוטומטית.</p>
<h2>איפה זה משתלב</h2>
<p>לרוב הקוראים שלנו זה מהווה קונטקסט ולא כלי לאימוץ כבר היום. זה חשוב מכיוון שחשיבה מגולמת היא התחום שבו המעבדות הגדולות משקיעות בהמשך, והיכולות מגיעות למוצרים סמוכים — שיפורים בחשיבה מרחבית מופיעים בהבנת וידאו ובשליטה על מסך זמן רב לפני שהם מופיעים במחסן.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-robotics-er-2-public-preview' AND lang = 'fr';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-robotics-er-2-public-preview', 'fr', 'models', $t$Modèles$t$, '#7c6af7', $t$Google$t$, '2026-07-30', $t$Gemini Robotics ER 2 entre en préversion publique avec coordination multi-robots$t$, $t$Google a ouvert la préversion publique de Gemini Robotics ER 2 avec deux points de terminaison : gemini-robotics-er-2-preview pour le raisonnement spatial avancé et la coordination multi-robots, et une variante en streaming optimisée pour un usage en temps réel via la Live API. La génération précédente, gemini-robotics-er-1.6-preview, sera arrêtée le 31 août 2026.$t$, $t$<p>Google a ouvert la <strong>préversion publique de Gemini Robotics ER 2</strong>, la gamme de raisonnement incarné destinée à la robotique plutôt qu'au chat.</p>
<h2>Ce qui a été lancé</h2>
<p>Deux points de terminaison sont disponibles. <strong>gemini-robotics-er-2-preview</strong> gère le raisonnement spatial avancé et la <strong>coordination multi-robots</strong> — planifier l'action de plusieurs machines travaillant dans le même espace plutôt que de piloter un seul robot isolément. <strong>gemini-robotics-er-2-streaming-preview</strong> est optimisé pour le streaming de texte en temps réel via la Live API, pour les cas où un robot ne peut pas attendre une réponse complète avant d'agir.</p>
<h2>Date limite de migration</h2>
<p>La génération précédente, <strong>gemini-robotics-er-1.6-preview, sera arrêtée le 31 août 2026</strong>. Quiconque construit sur la version 1.6 a désormais une date butoir pour migrer. Les points de terminaison en préversion ne comportent aucune garantie de stabilité, et ceci en est un rappel concret.</p>
<h2>Pourquoi c'est important</h2>
<p>La coordination multi-robots est l'élément intéressant. La manipulation à bras unique est un problème suffisamment résolu pour que la frontière se soit déplacée vers des machines qui partagent un espace de travail et doivent raisonner les unes par rapport aux autres. C'est la différence entre une démonstration et un entrepôt.</p>
<p>Le point de terminaison en streaming pointe vers le même changement. La robotique dispose d'un budget de latence que le chat n'a pas — une réponse qui arrive après que le moment soit passé est pire que l'absence de réponse. Construire une voie de streaming dédiée suggère que cette contrainte est prise au sérieux plutôt qu'ignorée.</p>
<p>Il s'agit encore d'un logiciel en préversion, avec une dépréciation déjà programmée pour son prédécesseur. Utile pour l'évaluation, mais pas encore de quoi bâtir une ligne de production.</p>
<h2>Comprendre la dépréciation</h2>
<p>L'arrêt d'ER 1.6 le 31 août, coïncidant avec la préversion d'ER 2, mérite d'être noté en soi. Environ un mois de chevauchement représente une fenêtre de migration courte pour des travaux de robotique, où les changements doivent être validés sur du matériel physique plutôt que sur une suite de tests.</p>
<p>Quiconque évalue cette gamme devrait supposer que le même rythme s'appliquera à l'avenir et le budgétiser. Les points de terminaison en préversion en robotique comportent un coût que les points de terminaison en préversion pour le chat n'ont pas : le travail d'intégration réside en partie dans la configuration physique, et cela ne se transpose pas automatiquement.</p>
<h2>Sa place dans l'écosystème</h2>
<p>Pour la majorité de notre audience, il s'agit davantage de contexte que d'un outil à adopter dès aujourd'hui. C'est important parce que le raisonnement incarné est le domaine dans lequel les grands laboratoires investissent désormais, et les capacités développées se retrouvent dans des produits adjacents — les améliorations du raisonnement spatial apparaissent dans la compréhension vidéo et le contrôle d'écran bien avant d'apparaître dans un entrepôt.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-robotics-er-2-public-preview' AND lang = 'pt';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-robotics-er-2-public-preview', 'pt', 'models', $t$Modelos$t$, '#7c6af7', $t$Google$t$, '2026-07-30', $t$Gemini Robotics ER 2 chega ao preview público com coordenação multirrobô$t$, $t$O Google abriu o preview público do Gemini Robotics ER 2 com dois endpoints: gemini-robotics-er-2-preview, para raciocínio espacial avançado e coordenação multirrobô, e uma variante em streaming otimizada para uso em tempo real via Live API. A geração anterior, gemini-robotics-er-1.6-preview, será desativada em 31 de agosto de 2026.$t$, $t$<p>O Google abriu o <strong>preview público do Gemini Robotics ER 2</strong>, a linha de raciocínio corporificado voltada para robótica, e não para chat.</p>
<h2>O que foi lançado</h2>
<p>Dois endpoints estão disponíveis. O <strong>gemini-robotics-er-2-preview</strong> lida com raciocínio espacial avançado e <strong>coordenação multirrobô</strong> — planejamento envolvendo várias máquinas atuando no mesmo espaço, em vez de conduzir uma única de forma isolada. Já o <strong>gemini-robotics-er-2-streaming-preview</strong> é otimizado para streaming de texto em tempo real por meio da Live API, para casos em que o robô não pode esperar uma resposta completa antes de agir.</p>
<h2>Prazo de migração</h2>
<p>A geração anterior, <strong>gemini-robotics-er-1.6-preview, será desativada em 31 de agosto de 2026</strong>. Quem estiver construindo sobre a versão 1.6 tem uma data limite para migrar. Endpoints em preview não oferecem garantia de estabilidade, e este é um lembrete prático do que isso significa.</p>
<h2>Por que isso importa</h2>
<p>A coordenação multirrobô é a parte mais interessante. A manipulação com um único braço já é um problema suficientemente resolvido, o que fez a fronteira avançar para máquinas que compartilham um espaço de trabalho e precisam raciocinar umas sobre as outras. Essa é a diferença entre uma demonstração e um armazém.</p>
<p>O endpoint de streaming aponta para a mesma mudança. A robótica tem um orçamento de latência que o chat não tem — uma resposta que chega depois que o momento já passou é piorque nenhuma resposta. A criação de um caminho de streaming dedicado sugere que essa restrição está sendo tratada com seriedade, e não apenas contornada.</p>
<p>Isso ainda é um software em preview, com uma descontinuação já programada para seu antecessor. Útil para avaliação, mas ainda não é algo sobre o qual construir uma linha de produção.</p>
<h2>Lendo a descontinuação</h2>
<p>O fato de a desativação do ER 1.6, em 31 de agosto, coincidir com o dia do preview do ER 2 já merece atenção por si só. Cerca de um mês de sobreposição é uma janela de migração curta para trabalhos em robótica, nos quais as mudanças precisam ser validadas em hardware físico, e não apenas em uma suíte de testes.</p>
<p>Quem estiver avaliando essa linha deve presumir que o mesmo ritmo se aplicará no futuro e planejar-se de acordo. Endpoints em preview na robótica trazem um custo que endpoints em preview no chat não trazem: parte do trabalho de integração está na configuração física, e isso não é transferido automaticamente.</p>
<h2>Onde isso se encaixa</h2>
<p>Para a maior parte do nosso público, isso é contexto, não uma ferramenta para adotar hoje. Importa porque o raciocínio corporificado é onde os grandes laboratórios estão investindo a seguir, e as capacidades acabam chegando a produtos adjacentes — melhorias no raciocínio espacial aparecem na compreensão de vídeo e no controle de tela bem antes de chegarem a um armazém.</p>$t$, true);

DELETE FROM news WHERE slug = 'openai-gpt-56-luna-80-percent-price-cut' AND lang = 'es';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('openai-gpt-56-luna-80-percent-price-cut', 'es', 'models', $t$Modelos$t$, '#7c6af7', $t$OpenAI$t$, '2026-07-30', $t$OpenAI reduce el precio de GPT-5.6 Luna a 0,20 $ por millón de tokens de entrada, una rebaja del 80%$t$, $t$OpenAI bajó el precio de GPT-5.6 Luna a 0,20 $ por millón de tokens de entrada y 1,20 $ por millón de tokens de salida. Luna se lanzó a 1 $ por millón de tokens de entrada, por lo que se trata de una rebaja del 80%. El resto de la familia se mantiene en Terra 2 $/12 $ y Sol 5 $/30 $ por millón de tokens.$t$, $t$<p>OpenAI ha reducido el precio de <strong>GPT-5.6 Luna</strong>, el modelo de entrada de la familia GPT-5.6, a <strong>0,20 $ por millón de tokens de entrada y 1,20 $ por millón de tokens de salida</strong>. Luna se lanzó a 1 $ por millón de tokens de entrada; la nueva cifra supone una rebaja del 80% en el lado de entrada.</p>
<h2>Qué ha cambiado</h2>
<p>La gama de tres modelos queda ahora así: <strong>Luna a 0,20 $ / 1,20 $</strong>, <strong>Terra a 2 $ / 12 $</strong> y <strong>Sol a 5 $ / 30 $</strong> por millón de tokens. Solo Luna se movió; Terra y Sol permanecen sin cambios.</p>
<p>El procesamiento por lotes (batch) se cobra a la mitad de la tarifa estándar en los tres modelos, y las solicitudes de contexto largo se facturan a aproximadamente el doble de la tarifa de contexto corto, por lo que el precio efectivo depende en gran medida de cómo esté planteada la carga de trabajo, no solo de qué modelo se elija.</p>
<h2>Dónde se ubica esto en el mercado</h2>
<p>Luna, con 0,20 $ de entrada, queda en el mismo rango que DeepSeek V4-Flash, a 0,14 $, y el nivel Flash-Lite de Google. Hace doce meses, la opción creíble más barata cercana a la frontera costaba varios dólares por millón de tokens de entrada. El suelo se ha movido un orden de magnitud, y lo hizo más rápido en el último trimestre.</p>
<h2>Por qué importa</h2>
<p>Para cualquier tarea de gran volumen —clasificación, extracción, enrutamiento, resumen de primera pasada— la factura del modelo deja de ser la limitación a estos niveles. Eso cambia qué productos merece la pena construir: flujos de trabajo que no eran rentables a 1 $ por millón de entradas se vuelven viables a 0,20 $.</p>
<p>La otra cara es que el precio por sí solo ya no diferencia al nivel económico. Cuando cuatro proveedores están a pocos céntimos entre sí, la decisión pasa a depender de la latencia, el manejo del contexto, la fiabilidad de las llamadas a herramientas y cómo se comporta el proveedor cuando necesita subir precios más adelante.</p>
<h2>Qué observar a continuación</h2>
<p>Una rebaja de este tamaño suele indicar capacidad disponible más que generosidad. La inferencia se abarata cuando un proveedor tiene hardware sobrante y una pila de servicio eficiente, y los precios lo reflejan. La pregunta para quien presupuesta con estas cifras es si el suelo se mantiene: DeepSeek ya ha anunciado públicamente que sus propios precios van a volver a subir.</p>
<p>La medida práctica es tratar el nivel económico como intercambiable. Mantener los prompts portables, evitar depender de funciones específicas de un proveedor en las rutas de mayor volumen y volver a comparar (benchmark) trimestralmente. A estos precios, la decisión de cambiar de proveedor debería basarse en la calidad según el propio conjunto de evaluación, no en una tabla de precios de lista que cambia cada pocas semanas.</p>$t$, true);

DELETE FROM news WHERE slug = 'openai-gpt-56-luna-80-percent-price-cut' AND lang = 'de';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('openai-gpt-56-luna-80-percent-price-cut', 'de', 'models', $t$Modelle$t$, '#7c6af7', $t$OpenAI$t$, '2026-07-30', $t$OpenAI senkt Preis für GPT-5.6 Luna auf 0,20 $ pro Million Input-Token – ein Rückgang von 80 %$t$, $t$OpenAI hat den Preis von GPT-5.6 Luna auf 0,20 $ pro Million Input-Token und 1,20 $ pro Million Output-Token gesenkt. Luna startete bei 1 $ pro Million Input-Token, was einer Senkung von 80 % entspricht. Der Rest der Familie bleibt bei Terra 2 $/12 $ und Sol 5 $/30 $ pro Million Token.$t$, $t$<p>OpenAI hat den Preis von <strong>GPT-5.6 Luna</strong>, dem Einstiegsmodell der GPT-5.6-Familie, auf <strong>0,20 $ pro Million Input-Token und 1,20 $ pro Million Output-Token</strong> gesenkt. Luna startete bei 1 $ pro Million Input-Token — die neue Zahl bedeutet auf der Input-Seite eine Senkung um 80 %.</p>
<h2>Was sich geändert hat</h2>
<p>Die dreiteilige Modellreihe kostet nun wie folgt: <strong>Luna 0,20 $ / 1,20 $</strong>, <strong>Terra 2 $ / 12 $</strong> und <strong>Sol 5 $ / 30 $</strong> pro Million Token. Nur Luna wurde angepasst; Terra und Sol bleiben unverändert.</p>
<p>Batch-Verarbeitung läuft bei allen drei Modellen zum halben Standardtarif, und Anfragen mit langem Kontext werden mit etwa dem doppelten Satz des Kurzkontext-Tarifs abgerechnet — der effektive Preis hängt also stark davon ab, wie eine Aufgabe gestaltet ist, nicht nur davon, welches Modell gewählt wird.</p>
<h2>Wo das im Markt einzuordnen ist</h2>
<p>Luna liegt mit 0,20 $ beim Input in derselben Preisklasse wie DeepSeek V4-Flash mit 0,14 $ und Googles Flash-Lite-Tarif. Vor zwölf Monaten kostete die günstigste ernstzunehmende, an die Spitzenmodelle angelehnte Option noch mehrere Dollar pro Million Input-Token. Die Preisuntergrenze hat sich um eine Größenordnung verschoben, und das am schnellsten im letzten Quartal.</p>
<h2>Warum das wichtig ist</h2>
<p>Für alles mit hohem Volumen — Klassifikation, Extraktion, Routing, erste Zusammenfassungen — hört die Modellrechnung bei diesen Preisen auf, der begrenzende Faktor zu sein. Das verändert, welche Produkte sich zu entwickeln lohnen: Workflows, die bei 1 $ pro Million Input-Token unwirtschaftlich waren, werden bei 0,20 $ tragfähig.</p>
<p>Die Kehrseite ist, dass der Preis allein die günstige Kategorie nicht mehr unterscheidet. Wenn vier Anbieter innerhalb weniger Cent voneinander liegen, verschiebt sich die Entscheidung auf Latenz, Kontextverarbeitung, Zuverlässigkeit beim Tool-Calling und darauf, wie sich der Anbieter verhält, wenn er später die Preise erhöhen muss.</p>
<h2>Was als Nächstes zu beobachten ist</h2>
<p>Eine Senkung dieser Größenordnung signalisiert meist Kapazität statt Großzügigkeit. Inferenz wird günstiger, wenn ein Anbieter über freie Hardware und einen effizienten Serving-Stack verfügt, und die Preise folgen entsprechend. Die Frage für alle, die mit diesen Zahlen kalkulieren, ist, ob die Preisuntergrenze hält — DeepSeek hat bereits öffentlich angekündigt, dass die eigenen Preise wieder steigen werden.</p>
<p>Der praktische Ansatz besteht darin, die günstige Kategorie als austauschbar zu behandeln. Prompts portabel halten, sich bei den Pfaden mit dem höchsten Volumen nicht auf anbieterspezifische Funktionen verlassen und vierteljährlich neu benchmarken. Bei diesen Preisen sollte die Wechselentscheidung von der Qualität im eigenen Evaluationsset abhängen, nicht von einer Preisliste, die sich alle paar Wochen ändert.</p>$t$, true);

DELETE FROM news WHERE slug = 'openai-gpt-56-luna-80-percent-price-cut' AND lang = 'ru';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('openai-gpt-56-luna-80-percent-price-cut', 'ru', 'models', $t$Модели$t$, '#7c6af7', $t$OpenAI$t$, '2026-07-30', $t$OpenAI снизила цену GPT-5.6 Luna до $0,20 за миллион входных токенов — сокращение на 80%$t$, $t$OpenAI снизила цену GPT-5.6 Luna до $0,20 за миллион входных токенов и $1,20 за миллион выходных токенов. Luna была запущена по цене $1 за миллион входных токенов, так что это сокращение на 80%. Остальные модели семейства сохраняют прежние цены: Terra — $2/$12, Sol — $5/$30 за миллион токенов.$t$, $t$<p>OpenAI снизила цену <strong>GPT-5.6 Luna</strong>, младшей модели семейства GPT-5.6, до <strong>$0,20 за миллион входных токенов и $1,20 за миллион выходных токенов</strong>. Luna была запущена по цене $1 за миллион входных токенов — новая цифра означает сокращение на 80% по входным токенам.</p>
<h2>Что изменилось</h2>
<p>Цены на три модели линейки теперь выглядят так: <strong>Luna — $0,20 / $1,20</strong>, <strong>Terra — $2 / $12</strong> и <strong>Sol — $5 / $30</strong> за миллион токенов. Изменилась только Luna; Terra и Sol остались без изменений.</p>
<p>Пакетная обработка для всех трёх моделей обходится в половину стандартной ставки, а запросы с длинным контекстом оплачиваются примерно по удвоенной ставке относительно короткого контекста — так что фактическая цена во многом зависит от того, как устроена рабочая нагрузка, а не только от выбора модели.</p>
<h2>Место на рынке</h2>
<p>Luna с ценой $0,20 за входные токены оказывается в той же категории, что DeepSeek V4-Flash с ценой $0,14 и тариф Flash-Lite от Google. Двенадцать месяцев назад самый дешёвый достоверно близкий к топовому классу вариант стоил несколько долларов за миллион входных токенов. Нижняя планка сдвинулась на порядок, и быстрее всего это произошло в последнем квартале.</p>
<h2>Почему это важно</h2>
<p>Для любых высокообъёмных задач — классификации, извлечения данных, маршрутизации, первичного суммирования — счёт за модель на таком уровне цен перестаёт быть ограничением. Это меняет то, какие продукты стоит создавать: рабочие процессы, невыгодные при $1 за миллион входных токенов, становятся жизнеспособными при $0,20.</p>
<p>Обратная сторона в том, что одна лишь цена больше не выделяет бюджетный уровень. Когда четыре поставщика находятся в пределах нескольких центов друг от друга, решение зависит от задержки, работы с контекстом, надёжности вызова инструментов и того, как поставщик поведёт себя, когда позже придётся поднимать цены.</p>
<h2>На что обратить внимание далее</h2>
<p>Снижение такого масштаба обычно говорит о наличии свободных мощностей, а не о щедрости. Инференс дешевеет, когда у поставщика есть избыточное оборудование и эффективный стек обслуживания, и цены следуют за этим. Вопрос для тех, кто планирует бюджет исходя из этих цифр, — удержится ли нижняя планка: DeepSeek уже публично заявила, что собственные цены будут повышены.</p>
<p>Практический вывод — относиться к бюджетному уровню как к взаимозаменяемому. Стоит сохранять переносимость промптов, не полагаться на специфичные для поставщика функции на самых высокообъёмных участках и пересматривать сравнение раз в квартал. При таких ценах решение о переходе должно основываться на качестве по собственному набору оценок, а не на таблице прайс-листов, которая меняется каждые несколько недель.</p>$t$, true);

DELETE FROM news WHERE slug = 'openai-gpt-56-luna-80-percent-price-cut' AND lang = 'ua';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('openai-gpt-56-luna-80-percent-price-cut', 'ua', 'models', $t$Моделі$t$, '#7c6af7', $t$OpenAI$t$, '2026-07-30', $t$OpenAI знизила ціну GPT-5.6 Luna до $0,20 за мільйон вхідних токенів — падіння на 80%$t$, $t$OpenAI знизила ціну GPT-5.6 Luna до $0,20 за мільйон вхідних токенів і $1,20 за мільйон вихідних токенів. Luna виходила на ринок за $1 за мільйон вхідних токенів, тож це падіння на 80%. Решта лінійки залишається без змін: Terra — $2/$12, Sol — $5/$30 за мільйон токенів.$t$, $t$<p>OpenAI знизила ціну <strong>GPT-5.6 Luna</strong>, базової моделі родини GPT-5.6, до <strong>$0,20 за мільйон вхідних токенів і $1,20 за мільйон вихідних токенів</strong>. Luna виходила на ринок за $1 за мільйон вхідних токенів — нова цифра означає скорочення на 80% за вхідними токенами.</p>
<h2>Що змінилося</h2>
<p>Лінійка з трьох моделей тепер коштує так: <strong>Luna — $0,20 / $1,20</strong>, <strong>Terra — $2 / $12</strong> і <strong>Sol — $5 / $30</strong> за мільйон токенів. Змінилася лише Luna; Terra і Sol залишилися без змін.</p>
<p>Пакетна обробка (batch processing) коштує вдвічі дешевше за стандартний тариф для всіх трьох моделей, а запити з довгим контекстом тарифікуються приблизно вдвічі дорожче за короткий контекст — тож реальна ціна значною мірою залежить від структури навантаження, а не лише від вибору моделі.</p>
<h2>Місце на ринку</h2>
<p>Luna з ціною $0,20 за вхідні токени потрапляє в той самий діапазон, що й DeepSeek V4-Flash за $0,14 та рівень Flash-Lite від Google. Дванадцять місяців тому найдешевший достовірно передовий варіант коштував кілька доларів за мільйон вхідних токенів. Нижня межа зсунулася на порядок, і найшвидше це сталося за останній квартал.</p>
<h2>Чому це важливо</h2>
<p>Для будь-яких високообсягових задач — класифікації, вилучення даних, маршрутизації, попереднього узагальнення — рахунок за модель за таких цін перестає бути обмеженням. Це змінює, які продукти варто створювати: робочі процеси, що були нерентабельними за $1 за мільйон вхідних токенів, стають життєздатними за $0,20.</p>
<p>Зворотна сторона в тому, що сама ціна більше не виділяє дешевий рівень серед конкурентів. Коли чотири постачальники знаходяться в межах кількох центів один від одного, рішення переходить до затримки, обробки контексту, надійності викликів інструментів і того, як провайдер поводитиметься, коли йому доведеться підвищувати ціни в майбутньому.</p>
<h2>На що звернути увагу далі</h2>
<p>Таке значне знижен­ня зазвичай свідчить про надлишок потужностей, а не про щедрість. Інференс дешевшає, коли у провайдера є вільне обладнання та ефективний стек обслуговування, і ціни йдуть слідом. Питання для тих, хто планує бюджет на основі цих цифр, — чи утримається нижня межа: DeepSeek вже публічно заявила, що її власні ціни знову зростатимуть.</p>
<p>Практичний підхід — ставитися до дешевого рівня як до взаємозамінного. Тримайте промпти переносними, не покладайтеся на специфічні для провайдера функції на найбільш навантажених ділянках і перевіряйте показники щоквартально. За таких цін рішення про перехід має визначатися якістю на вашому власному наборі для оцінювання, а не таблицею прайс-листів, яка змінюється щодекілька тижнів.</p>$t$, true);

DELETE FROM news WHERE slug = 'openai-gpt-56-luna-80-percent-price-cut' AND lang = 'he';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('openai-gpt-56-luna-80-percent-price-cut', 'he', 'models', $t$מודלים$t$, '#7c6af7', $t$OpenAI$t$, '2026-07-30', $t$OpenAI מוזילה את GPT-5.6 Luna ל-0.20$ למיליון טוקנים בכניסה — קיצוץ של 80%$t$, $t$OpenAI הורידה את מחיר GPT-5.6 Luna ל-0.20$ למיליון טוקנים בכניסה ו-1.20$ למיליון טוקנים ביציאה. Luna הושק במחיר של 1$ למיליון טוקנים בכניסה, כך שזהו קיצוץ של 80%. שאר המשפחה נותרה ללא שינוי: Terra ב-2$/12$ ו-Sol ב-5$/30$ למיליון טוקנים.$t$, $t$<p>OpenAI הורידה את מחיר <strong>GPT-5.6 Luna</strong>, המודל הבסיסי במשפחת GPT-5.6, ל-<strong>0.20$ למיליון טוקנים בכניסה ו-1.20$ למיליון טוקנים ביציאה</strong>. Luna הושק במחיר של 1$ למיליון טוקנים בכניסה — הנתון החדש מהווה קיצוץ של 80% בצד הכניסה.</p>
<h2>מה השתנה</h2>
<p>מבנה המחירים של שלושת המודלים כעת הוא כך: <strong>Luna ב-0.20$ / 1.20$</strong>, <strong>Terra ב-2$ / 12$</strong> ו-<strong>Sol ב-5$ / 30$</strong> למיליון טוקנים. רק Luna השתנה; Terra ו-Sol נותרו ללא שינוי.</p>
<p>עיבוד באצווה (Batch) מתבצע במחצית מהתעריף הרגיל בכל שלושת המודלים, ובקשות עם הקשר ארוך (long-context) מחויבות בכפול בקירוב מהתעריף להקשר קצר — כך שהמחיר האפקטיבי תלוי במידה רבה באופן שבו בנוי העומס, לא רק באיזה מודל נבחר.</p>
<h2>המיקום בשוק</h2>
<p>Luna במחיר של 0.20$ בכניסה נמצא באותה קטגוריה עם DeepSeek V4-Flash ב-0.14$ ועם רמת Flash-Lite של Google. לפני שנים עשר חודשים, האפשרות הזולה ביותר שנחשבה קרובה לחוד החזית עלתה כמה דולרים למיליון טוקנים בכניסה. הרצפה זזה בסדר גודל, והתנועה הזו הייתה המהירה ביותר ברביע האחרון.</p>
<h2>למה זה חשוב</h2>
<p>לכל שימוש בנפח גבוה — סיווג, חילוץ מידע, ניתוב, סיכום ראשוני — חשבון המודל מפסיק להיות המגבלה במחירים האלה. זה משנה אילו מוצרים משתלם לבנות: תהליכי עבודה שלא היו כלכליים במחיר של 1$ למיליון כניסות הופכים לכדאיים ב-0.20$.</p>
<p>מנגד, המחיר לבדו כבר לא מבדיל בין השחקנים בשכבה הזולה. כשארבעה ספקים נמצאים במרחק של כמה סנטים זה מזה, ההחלטה עוברת לזמן תגובה, טיפול בהקשר, מהימנות בקריאה לכלים (tool-calling) ואופן ההתנהגות של הספק כשהוא יצטרך להעלות מחירים בעתיד.</p>
<h2>מה לעקוב אחריו בהמשך</h2>
<p>קיצוץ בגודל הזה מסמן בדרך כלל קיבולת (capacity) ולא נדיבות. עלות ההסקה (inference) פוחתת כאשר לספק יש חומרה פנויה וערימת הגשה (serving stack) יעילה, והמחירים עוקבים בהתאם. השאלה לכל מי שמתכנן תקציב סביב הנתונים האלה היא אם הרצפה תישאר יציבה — DeepSeek כבר הודיעה בפומבי שהמחירים שלה עצמה עומדים לעלות בחזרה.</p>
<p>הצעד המעשי הוא להתייחס לשכבה הזולה כניתנת להחלפה. יש לשמור על פרומפטים ניידים, להימנע מהתבססות על תכונות ספציפיות לספק בנתיבי הנפח הגבוה ביותר, ולבצע השוואת ביצועים (benchmark) מחדש כל רבעון. במחירים האלה, החלטת המעבר צריכה להיות מונחית על ידי איכות במבחן ההערכה הפרטי שלך, ולא על ידי טבלת מחירי מחירון שמשתנה כל כמה שבועות.</p>$t$, true);

DELETE FROM news WHERE slug = 'openai-gpt-56-luna-80-percent-price-cut' AND lang = 'fr';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('openai-gpt-56-luna-80-percent-price-cut', 'fr', 'models', $t$Modèles$t$, '#7c6af7', $t$OpenAI$t$, '2026-07-30', $t$OpenAI réduit le prix de GPT-5.6 Luna à 0,20 $ par million de tokens en entrée, une baisse de 80 %$t$, $t$OpenAI a fait baisser le prix de GPT-5.6 Luna à 0,20 $ par million de tokens en entrée et 1,20 $ par million de tokens en sortie. Luna avait été lancé à 1 $ par million de tokens en entrée, ce qui représente donc une baisse de 80 %. Le reste de la famille reste inchangé, avec Terra à 2 $/12 $ et Sol à 5 $/30 $ par million de tokens.$t$, $t$<p>OpenAI a réduit le prix de <strong>GPT-5.6 Luna</strong>, le modèle d'entrée de gamme de la famille GPT-5.6, à <strong>0,20 $ par million de tokens en entrée et 1,20 $ par million de tokens en sortie</strong>. Luna avait été lancé à 1 $ par million de tokens en entrée — le nouveau tarif représente une baisse de 80 % côté entrée.</p>
<h2>Ce qui change</h2>
<p>La gamme de trois modèles se présente désormais ainsi : <strong>Luna à 0,20 $ / 1,20 $</strong>, <strong>Terra à 2 $ / 12 $</strong> et <strong>Sol à 5 $ / 30 $</strong> par million de tokens. Seul Luna a bougé ; Terra et Sol restent inchangés.</p>
<p>Le traitement par lots (batch) fonctionne à la moitié du tarif standard pour les trois modèles, et les requêtes à contexte long sont facturées à environ le double du tarif à contexte court — le prix effectif dépend donc fortement de la structure de la charge de travail, pas seulement du modèle choisi.</p>
<h2>Où cela se situe sur le marché</h2>
<p>Luna à 0,20 $ en entrée se retrouve dans la même catégorie que DeepSeek V4-Flash à 0,14 $ et le niveau Flash-Lite de Google. Il y a douze mois, l'option la moins chère et crédible proche de la frontière technologique coûtait plusieurs dollars par million de tokens en entrée. Le plancher a baissé d'un ordre de grandeur, et la baisse s'est accélérée au cours du dernier trimestre.</p>
<h2>Pourquoi c'est important</h2>
<p>Pour tout usage à fort volume — classification, extraction, routage, résumé de première passe — la facture liée au modèle cesse d'être la contrainte à ces niveaux de prix. Cela change les produits qu'il devient rentable de développer : des workflows qui n'étaient pas viables économiquement à 1 $ par million d'entrées le deviennent à 0,20 $.</p>
<p>L'autre facette est que le prix seul ne suffit plus à différencier les offres d'entrée de gamme. Lorsque quatre fournisseurs se situent à quelques centimes les uns des autres, la décision repose sur la latence, la gestion du contexte, la fiabilité des appels d'outils et le comportement du fournisseur lorsqu'il devra à nouveau augmenter ses prix.</p>
<h2>Ce qu'il faut surveiller ensuite</h2>
<p>Une baisse de cette ampleur signale généralement une question de capacité plutôt que de générosité. L'inférence devient moins chère lorsqu'un fournisseur dispose de matériel disponible et d'une pile de service efficace, et les prix suivent. La question pour ceux qui budgétisent sur ces chiffres est de savoir si ce plancher va tenir — DeepSeek a déjà annoncé publiquement que ses propres prix allaient repartir à la hausse.</p>
<p>La démarche pratique consiste à considérer le niveau d'entrée comme interchangeable. Il faut garder des prompts portables, éviter de s'appuyer sur des fonctionnalités propres à un fournisseur pour les chemins à plus fort volume, et refaire des benchmarks chaque trimestre. À ces prix, la décision de changer de fournisseur devrait être guidée par la qualité mesurée sur votre propre ensemble d'évaluation, et non par un tableau de prix affichés qui change toutes les quelques semaines.</p>$t$, true);

DELETE FROM news WHERE slug = 'openai-gpt-56-luna-80-percent-price-cut' AND lang = 'pt';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('openai-gpt-56-luna-80-percent-price-cut', 'pt', 'models', $t$Modelos$t$, '#7c6af7', $t$OpenAI$t$, '2026-07-30', $t$OpenAI reduz preço do GPT-5.6 Luna para US$ 0,20 por milhão de tokens de entrada — corte de 80%$t$, $t$A OpenAI reduziu o preço do GPT-5.6 Luna para US$ 0,20 por milhão de tokens de entrada e US$ 1,20 por milhão de tokens de saída. O Luna foi lançado a US$ 1 por milhão de tokens de entrada, o que representa um corte de 80%. O restante da família permanece nos mesmos valores: Terra a US$ 2/US$ 12 e Sol a US$ 5/US$ 30 por milhão de tokens.$t$, $t$<p>A OpenAI reduziu o preço do <strong>GPT-5.6 Luna</strong>, o modelo de entrada da família GPT-5.6, para <strong>US$ 0,20 por milhão de tokens de entrada e US$ 1,20 por milhão de tokens de saída</strong>. O Luna foi lançado a US$ 1 por milhão de tokens de entrada — o novo valor representa uma redução de 80% no lado da entrada.</p>
<h2>O que mudou</h2>
<p>Os três modelos da linha agora têm os seguintes preços: <strong>Luna a US$ 0,20 / US$ 1,20</strong>, <strong>Terra a US$ 2 / US$ 12</strong> e <strong>Sol a US$ 5 / US$ 30</strong> por milhão de tokens. Apenas o Luna teve alteração; Terra e Sol permanecem inalterados.</p>
<p>O processamento em lote (batch) custa metade da taxa padrão nos três modelos, e as solicitações de contexto longo são cobradas a aproximadamente o dobro da taxa de contexto curto — assim, o preço efetivo depende fortemente de como a carga de trabalho é estruturada, e não apenas de qual modelo é escolhido.</p>
<h2>Onde isso se encaixa no mercado</h2>
<p>O Luna, a US$ 0,20 na entrada, fica na mesma faixa do DeepSeek V4-Flash, a US$ 0,14, e do nível Flash-Lite do Google. Doze meses atrás, a opção mais barata e credível próxima da fronteira tecnológica custava vários dólares por milhão de tokens de entrada. O piso de preços caiu em uma ordem de magnitude, e essa queda se acelerou no último trimestre.</p>
<h2>Por que isso importa</h2>
<p>Para qualquer aplicação de alto volume — classificação, extração, roteamento, sumarização inicial — a conta do modelo deixa de ser o fator limitante nesses níveis de preço. Isso muda quais produtos vale a pena construir: fluxos de trabalho que eram inviáveis economicamente a US$ 1 por milhão de entradas passam a ser viáveis a US$ 0,20.</p>
<p>Por outro lado, o preço isolado já não diferencia mais o nível mais barato. Quando quatro fornecedores estão a poucos centavos de diferença entre si, a decisão passa a depender de latência, tratamento de contexto, confiabilidade nas chamadas de ferramentas e do comportamento do fornecedor quando precisar aumentar os preços mais adiante.</p>
<h2>O que observar a seguir</h2>
<p>Um corte desse tamanho geralmente indica capacidade disponível, não generosidade. A inferência fica mais barata quando um fornecedor tem hardware ocioso e uma pilha de serviço eficiente, e os preços acompanham essa realidade. A questão para quem planeja orçamentos com base nesses números é se esse piso vai se manter — o DeepSeek já declarou publicamente que seus próprios preços vão subir novamente.</p>
<p>A atitude prática é tratar o nível mais barato como intercambiável. Mantenha os prompts portáveis, evite depender de recursos específicos de um fornecedor nos caminhos de maior volume e refaça as comparações trimestralmente. Nesses preços, a decisão de troca deve ser guiada pela qualidade no seu próprio conjunto de avaliação, não por uma tabela de preços de lista que muda a cada poucas semanas.</p>$t$, true);

DELETE FROM news WHERE slug = 'gemini-robotics-er-2-public-preview' AND lang = 'ru';
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published)
VALUES ('gemini-robotics-er-2-public-preview', 'ru', 'models', $t$Модели$t$, '#7c6af7', $t$Google$t$, 'July 30, 2026', $t$Gemini Robotics ER 2 вышла в публичное превью с координацией нескольких роботов$t$, $t$Google открыла публичное превью Gemini Robotics ER 2 с двумя конечными точками: gemini-robotics-er-2-preview для продвинутого пространственного мышления и координации нескольких роботов и потоковый вариант для работы в реальном времени через Live API. Предыдущее поколение, gemini-robotics-er-1.6-preview, отключают 31 августа 2026 года.$t$, $t$<p>Google открыла <strong>публичное превью Gemini Robotics ER 2</strong> — линейки воплощённого мышления, нацеленной на робототехнику, а не на чат.</p>
<h2>Что вышло</h2>
<p>Доступны две конечные точки. <strong>gemini-robotics-er-2-preview</strong> отвечает за продвинутое пространственное мышление и <strong>координацию нескольких роботов</strong> — планирование сразу для машин, работающих в одном пространстве, а не управление одной в отрыве от остальных. <strong>gemini-robotics-er-2-streaming-preview</strong> оптимизирована под потоковую выдачу текста в реальном времени через Live API — для случаев, когда робот не может ждать полного ответа, прежде чем начать действовать.</p>
<h2>Срок миграции</h2>
<p>Предыдущее поколение, <strong>gemini-robotics-er-1.6-preview, отключат 31 августа 2026 года</strong>. У тех, кто строил на 1.6, есть жёсткая дата перехода. Превью-эндпоинты не дают гарантий стабильности, и это напоминание о том, что означает на практике.</p>
<h2>Почему это важно</h2>
<p>Самое интересное здесь — координация нескольких роботов. Манипуляция одной рукой решена достаточно, чтобы фронтир сместился к машинам, которые делят рабочее пространство и вынуждены учитывать друг друга. Это и есть разница между демонстрацией и складом.</p>
<p>Потоковая конечная точка указывает на тот же сдвиг. У робототехники бюджет задержки не такой, как у чата: ответ, пришедший после того, как момент упущен, хуже, чем отсутствие ответа. Отдельный потоковый путь говорит о том, что ограничение восприняли всерьёз, а не замазали.</p>
<p>Это по-прежнему превью-софт, у предшественника которого уже назначена дата отключения. Годится для оценки, но не для того, чтобы строить на нём производственную линию.</p>
<h2>Как читать депрекацию</h2>
<p>То, что отключение ER 1.6 объявлено в один день с превью ER 2, само по себе показательно. Примерно месяц на переход — короткое окно для робототехники, где изменения приходится проверять на физическом железе, а не прогоном тестов.</p>
<p>Всем, кто оценивает эту линейку, стоит исходить из того, что такой ритм сохранится, и закладывать его в план. Превью-эндпоинты в робототехнике обходятся дороже, чем в чате: часть интеграционной работы лежит в физической обвязке, а она не переносится автоматически.</p>
<h2>Кому это сейчас</h2>
<p>Для большинства нашей аудитории это контекст, а не инструмент для внедрения сегодня. Важно оно потому, что воплощённое мышление — направление, куда крупные лаборатории тратят следующий бюджет, и возможности оттуда приходят в соседние продукты: улучшения пространственного мышления появляются в понимании видео и управлении экраном заметно раньше, чем на складе.</p>$t$, true);
